insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3cdc877d-eb12-5662-aafc-8f5ce16d0f2c', '5cb5e738-220a-4267-901a-841c834b5d56', '555', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ أَيْمَنَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَالَّذِي ذَهَبَ بِهِ مَا تَرَكَهُمَا حَتَّى لَقِيَ اللَّهَ وَمَا لَقِيَ اللَّهَ تَعَالَى حَتَّى ثَقُلَ عَنْ الصَّلَاةِ وَكَانَ ‏ ‏يُصَلِّي كَثِيرًا مِنْ صَلَاتِهِ قَاعِدًا تَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهِمَا وَلَا يُصَلِّيهِمَا فِي الْمَسْجِدِ مَخَافَةَ أَنْ يُثَقِّلَ عَلَى أُمَّتِهِ وَكَانَ يُحِبُّ مَا يُخَفِّفُ عَنْهُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0df20719-0d86-5fe1-9054-30df7ea6b4a8', '5cb5e738-220a-4267-901a-841c834b5d56', '556', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏ابْنَ أُخْتِي ‏ ‏مَا تَرَكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّجْدَتَيْنِ بَعْدَ الْعَصْرِ عِنْدِي قَطُّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1b299e43-4cac-5504-bec2-a7f0863c611a', '5cb5e738-220a-4267-901a-841c834b5d56', '557', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَكْعَتَانِ لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَعُهُمَا سِرًّا وَلَا عَلَانِيَةً رَكْعَتَانِ قَبْلَ صَلَاةِ الصُّبْحِ وَرَكْعَتَانِ بَعْدَ الْعَصْرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab735d46-f1f6-5215-b8ae-2608bd5e4058', '5cb5e738-220a-4267-901a-841c834b5d56', '558', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَرْعَرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ رَأَيْتُ ‏ ‏الْأَسْوَدَ ‏ ‏وَمَسْرُوقًا ‏ ‏شَهِدَا عَلَى ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِينِي فِي يَوْمٍ بَعْدَ الْعَصْرِ إِلَّا صَلَّى رَكْعَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('763409bb-ed60-5ad1-a69f-c0cc99a8e768', '5cb5e738-220a-4267-901a-841c834b5d56', '559', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى هُوَ ابْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏أَنَّ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏حَدَّثَهُ قَالَ كُنَّا مَعَ ‏ ‏بُرَيْدَةَ ‏ ‏فِي يَوْمٍ ذِي غَيْمٍ فَقَالَ ‏ ‏بَكِّرُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَرَكَ صَلَاةَ الْعَصْرِ حَبِطَ عَمَلُهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2019a4e3-ade1-5ef8-a3ce-5bc0a0c71287', '5cb5e738-220a-4267-901a-841c834b5d56', '560', '‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ مَيْسَرَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سِرْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً فَقَالَ بَعْضُ الْقَوْمِ لَوْ ‏ ‏عَرَّسْتَ ‏ ‏بِنَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏أَخَافُ أَنْ تَنَامُوا عَنْ الصَّلَاةِ قَالَ ‏ ‏بِلَالٌ ‏ ‏أَنَا أُوقِظُكُمْ فَاضْطَجَعُوا وَأَسْنَدَ ‏ ‏بِلَالٌ ‏ ‏ظَهْرَهُ إِلَى رَاحِلَتِهِ فَغَلَبَتْهُ عَيْنَاهُ فَنَامَ فَاسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ طَلَعَ ‏ ‏حَاجِبُ الشَّمْسِ ‏ ‏فَقَالَ يَا ‏ ‏بِلَالُ ‏ ‏أَيْنَ مَا قُلْتَ قَالَ مَا أُلْقِيَتْ عَلَيَّ نَوْمَةٌ مِثْلُهَا قَطُّ قَالَ إِنَّ اللَّهَ قَبَضَ أَرْوَاحَكُمْ حِينَ شَاءَ وَرَدَّهَا عَلَيْكُمْ حِينَ شَاءَ يَا ‏ ‏بِلَالُ ‏ ‏قُمْ فَأَذِّنْ بِالنَّاسِ بِالصَّلَاةِ فَتَوَضَّأَ فَلَمَّا ارْتَفَعَتْ الشَّمْسُ وَابْيَاضَّتْ قَامَ فَصَلَّى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92b05b3f-06ba-5b55-ad02-f0fc8ed26548', '5cb5e738-220a-4267-901a-841c834b5d56', '561', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏جَاءَ يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏بَعْدَ مَا غَرَبَتْ الشَّمْسُ فَجَعَلَ يَسُبُّ كُفَّارَ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ مَا كِدْتُ أُصَلِّي الْعَصْرَ حَتَّى كَادَتْ الشَّمْسُ تَغْرُبُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ مَا صَلَّيْتُهَا فَقُمْنَا إِلَى ‏ ‏بُطْحَانَ ‏ ‏فَتَوَضَّأَ لِلصَّلَاةِ وَتَوَضَّأْنَا لَهَا فَصَلَّى الْعَصْرَ بَعْدَ مَا غَرَبَتْ الشَّمْسُ ثُمَّ صَلَّى بَعْدَهَا الْمَغْرِبَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9a5f63a1-af2f-5728-bde0-fda0ae7d9e9d', '5cb5e738-220a-4267-901a-841c834b5d56', '562', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَمُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّ إِذَا ذَكَرَهَا لَا كَفَّارَةَ لَهَا إِلَّا ذَلِكَ ‏ { ‏وَأَقِمْ الصَّلَاةَ لِذِكْرِي ‏} ‏قَالَ ‏ ‏مُوسَى ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏سَمِعْتُهُ يَقُولُ بَعْدُ ‏ ‏وَأَقِمْ الصَّلَاةَ للذِّكْرَى ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏وَقَالَ ‏ ‏حَبَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('75deb085-6838-50bb-9cf2-c1c7573fa0c7', '5cb5e738-220a-4267-901a-841c834b5d56', '563', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى الْقَطَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى هُوَ ابْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَعَلَ ‏ ‏عُمَرُ ‏ ‏يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏يَسُبُّ كُفَّارَهُمْ وَقَالَ مَا كِدْتُ أُصَلِّي الْعَصْرَ حَتَّى غَرَبَتْ قَالَ فَنَزَلْنَا ‏ ‏بُطْحَانَ ‏ ‏فَصَلَّى بَعْدَ مَا غَرَبَتْ الشَّمْسُ ثُمَّ صَلَّى الْمَغْرِبَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6c068fe0-94dd-5cdc-a923-6183ca7bb7eb', '5cb5e738-220a-4267-901a-841c834b5d56', '564', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْمِنْهَالِ ‏ ‏قَالَ انْطَلَقْتُ مَعَ أَبِي إِلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏فَقَالَ لَهُ أَبِي ‏ ‏حَدِّثْنَا ‏ ‏كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَكْتُوبَةَ قَالَ كَانَ ‏ ‏يُصَلِّي ‏ ‏الْهَجِيرَ ‏ ‏وَهِيَ الَّتِي تَدْعُونَهَا الْأُولَى حِينَ ‏ ‏تَدْحَضُ ‏ ‏الشَّمْسُ وَيُصَلِّي الْعَصْرَ ثُمَّ يَرْجِعُ أَحَدُنَا إِلَى أَهْلِهِ فِي أَقْصَى ‏ ‏الْمَدِينَةِ ‏ ‏وَالشَّمْسُ ‏ ‏حَيَّةٌ ‏ ‏وَنَسِيتُ مَا قَالَ فِي الْمَغْرِبِ قَالَ وَكَانَ يَسْتَحِبُّ أَنْ يُؤَخِّرَ الْعِشَاءَ قَالَ وَكَانَ يَكْرَهُ النَّوْمَ قَبْلَهَا وَالْحَدِيثَ بَعْدَهَا وَكَانَ ‏ ‏يَنْفَتِلُ ‏ ‏مِنْ صَلَاةِ الْغَدَاةِ حِينَ يَعْرِفُ أَحَدُنَا جَلِيسَهُ وَيَقْرَأُ مِنْ السِّتِّينَ إِلَى الْمِائَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('55cea2c7-1e8b-5cf4-b937-fbc44e22650c', '5cb5e738-220a-4267-901a-841c834b5d56', '565', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الصَّبَّاحِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَلِيٍّ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ بْنُ خَالِدٍ ‏ ‏قَالَ انْتَظَرْنَا ‏ ‏الْحَسَنَ ‏ ‏وَرَاثَ ‏ ‏عَلَيْنَا حَتَّى قَرُبْنَا مِنْ وَقْتِ قِيَامِهِ فَجَاءَ فَقَالَ دَعَانَا جِيرَانُنَا هَؤُلَاءِ ثُمَّ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏انْتَظَرْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ حَتَّى كَانَ ‏ ‏شَطْرُ ‏ ‏اللَّيْلِ يَبْلُغُهُ فَجَاءَ فَصَلَّى لَنَا ثُمَّ خَطَبَنَا فَقَالَ أَلَا إِنَّ النَّاسَ قَدْ صَلَّوْا ثُمَّ رَقَدُوا وَإِنَّكُمْ ‏ ‏لَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمْ الصَّلَاةَ قَالَ ‏ ‏الْحَسَنُ ‏ ‏وَإِنَّ الْقَوْمَ لَا يَزَالُونَ بِخَيْرٍ مَا انْتَظَرُوا الْخَيْرَ قَالَ ‏ ‏قُرَّةُ ‏ ‏هُوَ مِنْ حَدِيثِ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2d8823e1-e9da-5dbd-8863-f50bcab2771e', '5cb5e738-220a-4267-901a-841c834b5d56', '566', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَأَبُو بَكْرٍ ابْنُ أَبِي حَثْمَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ فِي آخِرِ حَيَاتِهِ فَلَمَّا سَلَّمَ قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَرَأَيْتَكُمْ لَيْلَتَكُمْ هَذِهِ فَإِنَّ رَأْسَ مِائَةٍ لَا يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ ‏ ‏فَوَهِلَ ‏ ‏النَّاسُ فِي مَقَالَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى مَا يَتَحَدَّثُونَ مِنْ هَذِهِ الْأَحَادِيثِ عَنْ مِائَةِ سَنَةٍ وَإِنَّمَا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ يُرِيدُ بِذَلِكَ أَنَّهَا تَخْرِمُ ذَلِكَ الْقَرْنَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be990035-93be-5af9-9c69-0ecf8b2cd064', '5cb5e738-220a-4267-901a-841c834b5d56', '567', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ الصُّفَّةِ ‏ ‏كَانُوا أُنَاسًا فُقَرَاءَ وَأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مَنْ كَانَ عِنْدَهُ طَعَامُ اثْنَيْنِ فَلْيَذْهَبْ بِثَالِثٍ وَإِنْ أَرْبَعٌ فَخَامِسٌ أَوْ سَادِسٌ وَأَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏جَاءَ بِثَلَاثَةٍ فَانْطَلَقَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَشَرَةٍ قَالَ فَهُوَ أَنَا وَأَبِي وَأُمِّي فَلَا أَدْرِي قَالَ وَامْرَأَتِي وَخَادِمٌ ‏ ‏بَيْنَنَا وَبَيْنَ بَيْتِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَإِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏تَعَشَّى عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ لَبِثَ حَيْثُ صُلِّيَتْ الْعِشَاءُ ثُمَّ رَجَعَ فَلَبِثَ حَتَّى تَعَشَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ بَعْدَ مَا مَضَى مِنْ اللَّيْلِ مَا شَاءَ اللَّهُ قَالَتْ لَهُ امْرَأَتُهُ وَمَا حَبَسَكَ عَنْ أَضْيَافِكَ ‏ ‏أَوْ قَالَتْ ضَيْفِكَ ‏ ‏قَالَ أَوَمَا ‏ ‏عَشَّيْتِيهِمْ قَالَتْ أَبَوْا حَتَّى تَجِيءَ قَدْ عُرِضُوا فَأَبَوْا قَالَ فَذَهَبْتُ أَنَا فَاخْتَبَأْتُ فَقَالَ يَا ‏ ‏غُنْثَرُ ‏ ‏فَجَدَّعَ ‏ ‏وَسَبَّ وَقَالَ كُلُوا لَا هَنِيئًا فَقَالَ وَاللَّهِ لَا أَطْعَمُهُ أَبَدًا وَايْمُ اللَّهِ ‏ ‏مَا كُنَّا نَأْخُذُ مِنْ لُقْمَةٍ إِلَّا ‏ ‏رَبَا ‏ ‏مِنْ أَسْفَلِهَا أَكْثَرُ مِنْهَا قَالَ ‏ ‏يَعْنِي حَتَّى شَبِعُوا وَصَارَتْ أَكْثَرَ مِمَّا كَانَتْ قَبْلَ ذَلِكَ فَنَظَرَ إِلَيْهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَإِذَا هِيَ كَمَا هِيَ أَوْ أَكْثَرُ مِنْهَا فَقَالَ لِامْرَأَتِهِ يَا أُخْتَ ‏ ‏بَنِي فِرَاسٍ ‏ ‏مَا هَذَا قَالَتْ لَا ‏ ‏وَقُرَّةِ عَيْنِي ‏ ‏لَهِيَ الْآنَ أَكْثَرُ مِنْهَا قَبْلَ ذَلِكَ بِثَلَاثِ مَرَّاتٍ فَأَكَلَ مِنْهَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَقَالَ إِنَّمَا كَانَ ذَلِكَ مِنْ الشَّيْطَانِ ‏ ‏يَعْنِي يَمِينَهُ ثُمَّ أَكَلَ مِنْهَا لُقْمَةً ثُمَّ حَمَلَهَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَصْبَحَتْ عِنْدَهُ وَكَانَ بَيْنَنَا وَبَيْنَ قَوْمٍ عَقْدٌ فَمَضَى الْأَجَلُ فَفَرَّقَنَا اثْنَا عَشَرَ رَجُلًا مَعَ كُلِّ رَجُلٍ مِنْهُمْ أُنَاسٌ اللَّهُ أَعْلَمُ كَمْ مَعَ كُلِّ رَجُلٍ فَأَكَلُوا مِنْهَا أَجْمَعُونَ أَوْ كَمَا قَالَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('00240a49-f9e6-5153-919d-aab3bcab8233', '5cb5e738-220a-4267-901a-841c834b5d56', '568', '‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ بْنُ مَيْسَرَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏ذَكَرُوا النَّارَ وَالنَّاقُوسَ فَذَكَرُوا ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏فَأُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَأَنْ يُوتِرَ الْإِقَامَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bacfb55c-220e-5213-b2f9-c78df310aca0', '5cb5e738-220a-4267-901a-841c834b5d56', '569', '‏ ‏حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَقُولُ ‏ ‏كَانَ الْمُسْلِمُونَ حِينَ قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏يَجْتَمِعُونَ ‏ ‏فَيَتَحَيَّنُونَ ‏ ‏الصَّلَاةَ لَيْسَ يُنَادَى لَهَا فَتَكَلَّمُوا يَوْمًا فِي ذَلِكَ فَقَالَ بَعْضُهُمْ اتَّخِذُوا نَاقُوسًا مِثْلَ نَاقُوسِ ‏ ‏النَّصَارَى ‏ ‏وَقَالَ بَعْضُهُمْ بَلْ بُوقًا مِثْلَ قَرْنِ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَوَلَا تَبْعَثُونَ رَجُلًا يُنَادِي بِالصَّلَاةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بِلَالُ ‏ ‏قُمْ فَنَادِ بِالصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b709f851-ed1f-5c62-82f8-45cfe6284446', '5cb5e738-220a-4267-901a-841c834b5d56', '570', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَأَنْ يُوتِرَ الْإِقَامَةَ إِلَّا الْإِقَامَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3acdf83f-0d8a-5842-b70b-ae334682b151', '5cb5e738-220a-4267-901a-841c834b5d56', '571', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَثُرَ النَّاسُ قَالَ ذَكَرُوا أَنْ يَعْلَمُوا وَقْتَ الصَّلَاةِ بِشَيْءٍ يَعْرِفُونَهُ فَذَكَرُوا أَنْ ‏ ‏يُورُوا ‏ ‏نَارًا أَوْ يَضْرِبُوا نَاقُوسًا ‏ ‏فَأُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَأَنْ يُوتِرَ الْإِقَامَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f5abde79-11a4-5729-80b9-9be46a391acd', '5cb5e738-220a-4267-901a-841c834b5d56', '572', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُمِرَ ‏ ‏بِلَالٌ ‏ ‏أَنْ ‏ ‏يَشْفَعَ ‏ ‏الْأَذَانَ وَأَنْ يُوتِرَ الْإِقَامَةَ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏فَذَكَرْتُ ‏ ‏لِأَيُّوبَ ‏ ‏فَقَالَ ‏ ‏إِلَّا الْإِقَامَةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('035daa88-52b1-597c-a5b3-b98d68bb6a22', '5cb5e738-220a-4267-901a-841c834b5d56', '573', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نُودِيَ لِلصَّلَاةِ أَدْبَرَ الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لَا يَسْمَعَ التَّأْذِينَ فَإِذَا قَضَى النِّدَاءَ أَقْبَلَ حَتَّى إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ أَدْبَرَ حَتَّى إِذَا قَضَى ‏ ‏التَّثْوِيبَ ‏ ‏أَقْبَلَ حَتَّى يَخْطِرَ بَيْنَ الْمَرْءِ وَنَفْسِهِ يَقُولُ اذْكُرْ كَذَا اذْكُرْ كَذَا لِمَا لَمْ يَكُنْ يَذْكُرُ حَتَّى يَظَلَّ الرَّجُلُ لَا يَدْرِي كَمْ صَلَّى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('56f49380-ebce-568f-a3d2-2c1f6579e2da', '5cb5e738-220a-4267-901a-841c834b5d56', '574', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ الْأَنْصَارِيِّ ثُمَّ الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ أَخْبَرَهُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏قَالَ لَهُ ‏ ‏إِنِّي أَرَاكَ تُحِبُّ الْغَنَمَ وَالْبَادِيَةَ فَإِذَا كُنْتَ فِي غَنَمِكَ أَوْ بَادِيَتِكَ فَأَذَّنْتَ بِالصَّلَاةِ فَارْفَعْ صَوْتَكَ بِالنِّدَاءِ ‏ ‏فَإِنَّهُ لَا يَسْمَعُ ‏ ‏مَدَى صَوْتِ ‏ ‏الْمُؤَذِّنِ جِنٌّ وَلَا إِنْسٌ وَلَا شَيْءٌ إِلَّا شَهِدَ لَهُ يَوْمَ الْقِيَامَةِ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fb943379-27be-5d81-a663-2ea664a991dd', '5cb5e738-220a-4267-901a-841c834b5d56', '575', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا غَزَا بِنَا قَوْمًا لَمْ يَكُنْ يَغْزُو بِنَا حَتَّى يُصْبِحَ وَيَنْظُرَ فَإِنْ سَمِعَ أَذَانًا كَفَّ عَنْهُمْ وَإِنْ لَمْ يَسْمَعْ أَذَانًا أَغَارَ عَلَيْهِمْ قَالَ فَخَرَجْنَا إِلَى ‏ ‏خَيْبَرَ ‏ ‏فَانْتَهَيْنَا إِلَيْهِمْ لَيْلًا فَلَمَّا أَصْبَحَ وَلَمْ يَسْمَعْ أَذَانًا رَكِبَ وَرَكِبْتُ خَلْفَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏وَإِنَّ قَدَمِي لَتَمَسُّ قَدَمَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَخَرَجُوا إِلَيْنَا ‏ ‏بِمَكَاتِلِهِمْ ‏ ‏وَمَسَاحِيهِمْ ‏ ‏فَلَمَّا رَأَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏وَاللَّهِ ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏قَالَ فَلَمَّا رَآهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ ‏ { ‏فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('141e71b5-167a-5207-83ed-4eae8fab7edd', '5cb5e738-220a-4267-901a-841c834b5d56', '576', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ النِّدَاءَ فَقُولُوا مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bfef38cf-6e68-540a-9866-48d702a9661a', '5cb5e738-220a-4267-901a-841c834b5d56', '577', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِيسَى بْنُ طَلْحَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُعَاوِيَةَ ‏ ‏يَوْمًا ‏ ‏فَقَالَ مِثْلَهُ إِلَى قَوْلِهِ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d70a91ea-63a0-5583-b9a7-7e0cb362f796', '5cb5e738-220a-4267-901a-841c834b5d56', '578', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ رَاهَوَيْهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏نَحْوَهُ قَالَ ‏ ‏يَحْيَى ‏ ‏وَحَدَّثَنِي ‏ ‏بَعْضُ إِخْوَانِنَا ‏ ‏أَنَّهُ قَالَ ‏ ‏لَمَّا قَالَ حَيَّ عَلَى الصَّلَاةِ قَالَ ‏ ‏لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ وَقَالَ هَكَذَا سَمِعْنَا نَبِيَّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6542b9d0-67aa-5ee8-9733-2b9ae6d526d4', '5cb5e738-220a-4267-901a-841c834b5d56', '579', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ ‏ ‏مُحَمَّدًا ‏ ‏الْوَسِيلَةَ ‏ ‏وَالْفَضِيلَةَ ‏ ‏وَابْعَثْهُ ‏ ‏مَقَامًا مَحْمُودًا ‏ ‏الَّذِي وَعَدْتَهُ ‏ ‏حَلَّتْ ‏ ‏لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f83e6bb5-46c9-5f55-a01b-87f0ce9bfa45', '5cb5e738-220a-4267-901a-841c834b5d56', '580', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ ‏ ‏يَسْتَهِمُوا ‏ ‏عَلَيْهِ ‏ ‏لَاسْتَهَمُوا ‏ ‏وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fcffd7f0-1364-5e1a-be7f-368d7ccea320', '5cb5e738-220a-4267-901a-841c834b5d56', '581', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏وَعَبْدِ الْحَمِيدِ ‏ ‏صَاحِبِ ‏ ‏الزِّيَادِيِّ ‏ ‏وَعَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏قَالَ خَطَبَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فِي ‏ ‏يَوْمٍ رَدْغٍ ‏ ‏فَلَمَّا بَلَغَ الْمُؤَذِّنُ حَيَّ عَلَى الصَّلَاةِ فَأَمَرَهُ أَنْ يُنَادِيَ ‏ ‏الصَّلَاةُ فِي ‏ ‏الرِّحَالِ ‏ ‏فَنَظَرَ الْقَوْمُ بَعْضُهُمْ إِلَى بَعْضٍ فَقَالَ فَعَلَ هَذَا مَنْ هُوَ خَيْرٌ مِنْهُ وَإِنَّهَا ‏ ‏عَزْمَةٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e57a632f-8ef9-538f-a330-e67395e2932d', '5cb5e738-220a-4267-901a-841c834b5d56', '582', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏ثُمَّ قَالَ وَكَانَ رَجُلًا أَعْمَى لَا يُنَادِي حَتَّى يُقَالَ لَهُ أَصْبَحْتَ أَصْبَحْتَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a1995d03-4ee7-58d1-aee3-c875ba11a5f8', '5cb5e738-220a-4267-901a-841c834b5d56', '583', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏حَفْصَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا اعْتَكَفَ الْمُؤَذِّنُ لِلصُّبْحِ وَبَدَا الصُّبْحُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ تُقَامَ الصَّلَاةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ec732995-2688-5b03-ac3a-ac26f75a6ef8', '5cb5e738-220a-4267-901a-841c834b5d56', '584', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ خَفِيفَتَيْنِ بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الصُّبْحِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('02294165-9645-52e8-ab01-845c8879a705', '5cb5e738-220a-4267-901a-841c834b5d56', '585', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8482cf2e-e07e-5107-b64e-c7b35e7a24c4', '5cb5e738-220a-4267-901a-841c834b5d56', '586', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمْنَعَنَّ أَحَدَكُمْ أَوْ أَحَدًا مِنْكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏مِنْ سَحُورِهِ فَإِنَّهُ يُؤَذِّنُ أَوْ يُنَادِي بِلَيْلٍ لِيَرْجِعَ قَائِمَكُمْ وَلِيُنَبِّهَ نَائِمَكُمْ وَلَيْسَ أَنْ يَقُولَ الْفَجْرُ أَوْ الصُّبْحُ وَقَالَ بِأَصَابِعِهِ وَرَفَعَهَا إِلَى فَوْقُ ‏ ‏وَطَأْطَأَ ‏ ‏إِلَى أَسْفَلُ حَتَّى يَقُولَ هَكَذَا ‏ ‏وَقَالَ ‏ ‏زُهَيْرٌ ‏ ‏بِسَبَّابَتَيْهِ إِحْدَاهُمَا فَوْقَ الْأُخْرَى ثُمَّ مَدَّهَا عَنْ يَمِينِهِ وَشِمَالِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab4df554-8403-5f0a-8eb6-4a0b6d8e3ce4', '5cb5e738-220a-4267-901a-841c834b5d56', '587', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَعَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏يُوسُفُ بْنُ عِيسَى الْمَرْوَزِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f07ee6e1-2d9c-54be-bc7f-d798ae70af82', '5cb5e738-220a-4267-901a-841c834b5d56', '588', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ الْوَاسِطِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ ثَلَاثًا لِمَنْ شَاءَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('793c5c0c-4551-52d1-9262-aecaa41748e9', '5cb5e738-220a-4267-901a-841c834b5d56', '589', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ عَامِرٍ الْأَنْصَارِيَّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ الْمُؤَذِّنُ إِذَا أَذَّنَ قَامَ نَاسٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْتَدِرُونَ ‏ ‏السَّوَارِيَ ‏ ‏حَتَّى يَخْرُجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمْ كَذَلِكَ يُصَلُّونَ الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ وَلَمْ يَكُنْ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ شَيْءٌ ‏ ‏قَالَ ‏ ‏عُثْمَانُ بْنُ جَبَلَةَ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏لَمْ يَكُنْ بَيْنَهُمَا إِلَّا قَلِيلٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('158a9e02-14fd-5ce1-9932-3193b7f18f96', '5cb5e738-220a-4267-901a-841c834b5d56', '590', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَكَتَ الْمُؤَذِّنُ بِالْأُولَى مِنْ صَلَاةِ الْفَجْرِ قَامَ فَرَكَعَ رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ بَعْدَ أَنْ يَسْتَبِينَ الْفَجْرُ ثُمَّ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ لِلْإِقَامَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d42d274d-3d30-56da-a55a-d3e5b42d2bea', '5cb5e738-220a-4267-901a-841c834b5d56', '591', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏كَهْمَسُ بْنُ الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ ثُمَّ قَالَ فِي الثَّالِثَةِ لِمَنْ شَاءَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a0a811a3-ea75-551f-9dea-6884fc588b95', '5cb5e738-220a-4267-901a-841c834b5d56', '592', '‏ ‏حَدَّثَنَا ‏ ‏مُعَلَّى بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏نَفَرٍ ‏ ‏مِنْ قَوْمِي فَأَقَمْنَا عِنْدَهُ عِشْرِينَ لَيْلَةً وَكَانَ رَحِيمًا رَفِيقًا فَلَمَّا رَأَى شَوْقَنَا إِلَى أَهَالِينَا قَالَ ‏ ‏ارْجِعُوا فَكُونُوا فِيهِمْ وَعَلِّمُوهُمْ وَصَلُّوا فَإِذَا حَضَرَتْ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fc4eb2b6-fb90-5e61-8076-62b17e886638', '5cb5e738-220a-4267-901a-841c834b5d56', '593', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْمُهَاجِرِ أَبِي الْحَسَنِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَأَرَادَ الْمُؤَذِّنُ أَنْ يُؤَذِّنَ فَقَالَ لَهُ ‏ ‏أَبْرِدْ ‏ ‏ثُمَّ أَرَادَ أَنْ يُؤَذِّنَ فَقَالَ لَهُ ‏ ‏أَبْرِدْ ‏ ‏ثُمَّ أَرَادَ أَنْ يُؤَذِّنَ فَقَالَ لَهُ ‏ ‏أَبْرِدْ ‏ ‏حَتَّى سَاوَى الظِّلُّ ‏ ‏التُّلُولَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4e2ada99-bee8-5cbc-9510-9a245213ffab', '5cb5e738-220a-4267-901a-841c834b5d56', '594', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلَانِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرِيدَانِ السَّفَرَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَنْتُمَا خَرَجْتُمَا فَأَذِّنَا ثُمَّ أَقِيمَا ثُمَّ لِيَؤُمَّكُمَا أَكْبَرُكُمَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f8b2d694-f55d-529d-8d52-00608290b05e', '5cb5e738-220a-4267-901a-841c834b5d56', '595', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏أَتَيْنَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ شَبَبَةٌ مُتَقَارِبُونَ فَأَقَمْنَا عِنْدَهُ عِشْرِينَ يَوْمًا وَلَيْلَةً وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِيمًا رَفِيقًا فَلَمَّا ظَنَّ أَنَّا قَدْ اشْتَهَيْنَا أَهْلَنَا أَوْ قَدْ اشْتَقْنَا سَأَلَنَا عَمَّنْ تَرَكْنَا بَعْدَنَا فَأَخْبَرْنَاهُ قَالَ ‏ ‏ارْجِعُوا إِلَى أَهْلِيكُمْ فَأَقِيمُوا فِيهِمْ وَعَلِّمُوهُمْ وَمُرُوهُمْ وَذَكَرَ أَشْيَاءَ أَحْفَظُهَا أَوْ لَا أَحْفَظُهَا وَصَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي فَإِذَا حَضَرَتْ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2783324a-bd9a-529f-85be-457a051c0e9f', '5cb5e738-220a-4267-901a-841c834b5d56', '596', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏أَذَّنَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فِي لَيْلَةٍ بَارِدَةٍ ‏ ‏بِضَجْنَانَ ‏ ‏ثُمَّ قَالَ صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏ ‏فَأَخْبَرَنَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْمُرُ مُؤَذِّنًا يُؤَذِّنُ ثُمَّ يَقُولُ عَلَى إِثْرِهِ ‏ ‏أَلَا صَلُّوا فِي ‏ ‏الرِّحَالِ ‏ ‏فِي اللَّيْلَةِ الْبَارِدَةِ أَوْ الْمَطِيرَةِ فِي السَّفَرِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ab602dfe-e827-535b-9302-4bb03332736b', '5cb5e738-220a-4267-901a-841c834b5d56', '597', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ مَنْصُورٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْعُمَيْسِ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْأَبْطَحِ ‏ ‏فَجَاءَهُ ‏ ‏بِلَالٌ ‏ ‏فَآذَنَهُ ‏ ‏بِالصَّلَاةِ ثُمَّ خَرَجَ ‏ ‏بِلَالٌ ‏ ‏بِالْعَنَزَةِ ‏ ‏حَتَّى رَكَزَهَا بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْأَبْطَحِ ‏ ‏وَأَقَامَ الصَّلَاةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d276a5e7-2831-5e1c-b162-48f683680e39', '5cb5e738-220a-4267-901a-841c834b5d56', '598', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ أَبِي جُحَيْفَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ رَأَى ‏ ‏بِلَالًا ‏ ‏يُؤَذِّنُ فَجَعَلْتُ ‏ ‏أَتَتَبَّعُ فَاهُ ‏ ‏هَهُنَا وَهَهُنَا بِالْأَذَانِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bbdac622-3d16-53c7-988f-3c1ebac7deca', '5cb5e738-220a-4267-901a-841c834b5d56', '599', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ نُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ سَمِعَ ‏ ‏جَلَبَةَ ‏ ‏رِجَالٍ فَلَمَّا صَلَّى قَالَ ‏ ‏مَا شَأْنُكُمْ قَالُوا اسْتَعْجَلْنَا إِلَى الصَّلَاةِ قَالَ فَلَا تَفْعَلُوا إِذَا أَتَيْتُمْ الصَّلَاةَ فَعَلَيْكُمْ ‏ ‏بِالسَّكِينَةِ ‏ ‏فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7c7463b9-7586-515b-9e04-c63863eccdbb', '5cb5e738-220a-4267-901a-841c834b5d56', '600', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ الْإِقَامَةَ فَامْشُوا إِلَى الصَّلَاةِ وَعَلَيْكُمْ ‏ ‏بِالسَّكِينَةِ ‏ ‏وَالْوَقَارِ ‏ ‏وَلَا تُسْرِعُوا فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0018c3e6-a2cc-5825-aad4-c91d0dfc782a', '5cb5e738-220a-4267-901a-841c834b5d56', '601', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ كَتَبَ إِلَيَّ ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('87355608-d4e5-5ddf-b9d1-b7c6602deb5e', '5cb5e738-220a-4267-901a-841c834b5d56', '602', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُقِيمَتْ الصَّلَاةُ فَلَا تَقُومُوا حَتَّى تَرَوْنِي وَعَلَيْكُمْ ‏ ‏بِالسَّكِينَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f8836c84-f7e9-564d-8272-e90504f3a355', '5cb5e738-220a-4267-901a-841c834b5d56', '603', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ وَقَدْ أُقِيمَتْ الصَّلَاةُ وَعُدِّلَتْ الصُّفُوفُ حَتَّى إِذَا قَامَ فِي مُصَلَّاهُ انْتَظَرْنَا أَنْ يُكَبِّرَ انْصَرَفَ قَالَ ‏ ‏عَلَى مَكَانِكُمْ فَمَكَثْنَا عَلَى هَيْئَتِنَا حَتَّى خَرَجَ إِلَيْنَا ‏ ‏يَنْطِفُ ‏ ‏رَأْسُهُ مَاءً وَقَدْ اغْتَسَلَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('42992968-3479-592a-a6db-d6ee648ea654', '5cb5e738-220a-4267-901a-841c834b5d56', '604', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَسَوَّى النَّاسُ صُفُوفَهُمْ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَقَدَّمَ وَهُوَ جُنُبٌ ثُمَّ قَالَ ‏ ‏عَلَى مَكَانِكُمْ فَرَجَعَ فَاغْتَسَلَ ثُمَّ خَرَجَ وَرَأْسُهُ يَقْطُرُ مَاءً فَصَلَّى بِهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eb8dec44-0de6-5329-9291-8c8ac6b2c57b', '5cb5e738-220a-4267-901a-841c834b5d56', '605', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يَقُولُ أَخْبَرَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَوْمَ ‏ ‏الْخَنْدَقِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ وَاللَّهِ مَا كِدْتُ أَنْ أُصَلِّيَ حَتَّى كَادَتْ الشَّمْسُ تَغْرُبُ وَذَلِكَ بَعْدَ مَا أَفْطَرَ الصَّائِمُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ مَا صَلَّيْتُهَا فَنَزَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏بُطْحَانَ ‏ ‏وَأَنَا مَعَهُ فَتَوَضَّأَ ثُمَّ صَلَّى ‏ ‏يَعْنِي الْعَصْرَ بَعْدَ مَا غَرَبَتْ الشَّمْسُ ثُمَّ صَلَّى بَعْدَهَا الْمَغْرِبَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('664d3fad-285e-5227-b44e-67dc6ce26cb2', '5cb5e738-220a-4267-901a-841c834b5d56', '606', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنَاجِي ‏ ‏رَجُلًا فِي جَانِبِ الْمَسْجِدِ فَمَا قَامَ إِلَى الصَّلَاةِ حَتَّى نَامَ الْقَوْمُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b8f43354-e24a-5fa7-bb6b-03bd87094674', '5cb5e738-220a-4267-901a-841c834b5d56', '607', '‏ ‏حَدَّثَنَا ‏ ‏عَيَّاشُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏قَالَ سَأَلْتُ ‏ ‏ثَابِتًا الْبُنَانِيَّ ‏ ‏عَنْ الرَّجُلِ يَتَكَلَّمُ بَعْدَ مَا تُقَامُ الصَّلَاةُ ‏ ‏فَحَدَّثَنِي عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَعَرَضَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَحَبَسَهُ بَعْدَ مَا أُقِيمَتْ الصَّلَاةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8069937c-9c43-5058-b56b-fcc45a94cede', '5cb5e738-220a-4267-901a-841c834b5d56', '608', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَقَدْ هَمَمْتُ أَنْ آمُرَ بِحَطَبٍ فَيُحْطَبَ ثُمَّ آمُرَ بِالصَّلَاةِ فَيُؤَذَّنَ لَهَا ثُمَّ آمُرَ رَجُلًا فَيَؤُمَّ النَّاسَ ثُمَّ ‏ ‏أُخَالِفَ ‏ ‏إِلَى رِجَالٍ فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ يَعْلَمُ أَحَدُهُمْ أَنَّهُ يَجِدُ عَرْقًا سَمِينًا أَوْ ‏ ‏مِرْمَاتَيْنِ ‏ ‏حَسَنَتَيْنِ ‏ ‏لَشَهِدَ ‏ ‏الْعِشَاءَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a077b95-1eb1-54a0-bd28-9f05cbb58101', '5cb5e738-220a-4267-901a-841c834b5d56', '609', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْجَمَاعَةِ تَفْضُلُ صَلَاةَ ‏ ‏الْفَذِّ ‏ ‏بِسَبْعٍ وَعِشْرِينَ دَرَجَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dd97aafa-1842-5461-b5a0-169adfe8947f', '5cb5e738-220a-4267-901a-841c834b5d56', '610', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صَلَاةُ الْجَمَاعَةِ تَفْضُلُ صَلَاةَ ‏ ‏الْفَذِّ ‏ ‏بِخَمْسٍ وَعِشْرِينَ دَرَجَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fc2d0df7-683a-55f3-ab46-c1aeeba101be', '5cb5e738-220a-4267-901a-841c834b5d56', '611', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَالِحٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ الرَّجُلِ فِي الْجَمَاعَةِ ‏ ‏تُضَعَّفُ ‏ ‏عَلَى صَلَاتِهِ فِي بَيْتِهِ وَفِي سُوقِهِ خَمْسًا وَعِشْرِينَ ضِعْفًا وَذَلِكَ أَنَّهُ إِذَا تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ ثُمَّ خَرَجَ إِلَى الْمَسْجِدِ لَا يُخْرِجُهُ إِلَّا الصَّلَاةُ لَمْ يَخْطُ خَطْوَةً إِلَّا رُفِعَتْ لَهُ بِهَا دَرَجَةٌ وَحُطَّ عَنْهُ بِهَا خَطِيئَةٌ فَإِذَا صَلَّى لَمْ تَزَلْ الْمَلَائِكَةُ تُصَلِّي عَلَيْهِ مَا دَامَ فِي مُصَلَّاهُ اللَّهُمَّ صَلِّ عَلَيْهِ اللَّهُمَّ ارْحَمْهُ وَلَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا انْتَظَرَ الصَّلَاةَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7b08b911-af89-5ea8-a9eb-a29f4d99a5b6', '5cb5e738-220a-4267-901a-841c834b5d56', '612', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَفْضُلُ صَلَاةُ الْجَمِيعِ صَلَاةَ أَحَدِكُمْ وَحْدَهُ بِخَمْسٍ وَعِشْرِينَ ‏ ‏جُزْءًا ‏ ‏وَتَجْتَمِعُ مَلَائِكَةُ اللَّيْلِ وَمَلَائِكَةُ النَّهَارِ فِي صَلَاةِ الْفَجْرِ ثُمَّ يَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏إِنَّ قُرْآنَ الْفَجْرِ كَانَ مَشْهُودًا ‏} ‏قَالَ ‏ ‏شُعَيْبٌ ‏ ‏وَحَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏تَفْضُلُهَا بِسَبْعٍ وَعِشْرِينَ دَرَجَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b86a9dd4-676f-5532-b67c-5379dc558799', '5cb5e738-220a-4267-901a-841c834b5d56', '613', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تَقُولُ دَخَلَ عَلَيَّ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏وَهُوَ مُغْضَبٌ فَقُلْتُ مَا أَغْضَبَكَ فَقَالَ ‏ ‏وَاللَّهِ مَا أَعْرِفُ مِنْ أُمَّةِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا إِلَّا أَنَّهُمْ يُصَلُّونَ جَمِيعًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('db34ffd4-c8cd-5b8b-93d2-69b0b36eabb3', '5cb5e738-220a-4267-901a-841c834b5d56', '614', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْظَمُ النَّاسِ أَجْرًا فِي الصَّلَاةِ أَبْعَدُهُمْ فَأَبْعَدُهُمْ مَمْشًى وَالَّذِي يَنْتَظِرُ الصَّلَاةَ حَتَّى يُصَلِّيَهَا مَعَ الْإِمَامِ أَعْظَمُ أَجْرًا مِنْ الَّذِي ‏ ‏يُصَلِّي ثُمَّ يَنَامُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d72b198-8dd8-55b5-af9c-0c1fdf076768', '5cb5e738-220a-4267-901a-841c834b5d56', '615', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ يَمْشِي بِطَرِيقٍ وَجَدَ غُصْنَ شَوْكٍ عَلَى الطَّرِيقِ ‏ ‏فَأَخَّرَهُ ‏ ‏فَشَكَرَ اللَّهُ لَهُ فَغَفَرَ لَهُ ثُمَّ قَالَ الشُّهَدَاءُ خَمْسَةٌ ‏ ‏الْمَطْعُونُ ‏ ‏وَالْمَبْطُونُ ‏ ‏وَالْغَرِيقُ ‏ ‏وَصَاحِبُ الْهَدْمِ ‏ ‏وَالشَّهِيدُ فِي سَبِيلِ اللَّهِ ‏ ‏وَقَالَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ثُمَّ لَمْ يَجِدُوا إِلَّا أَنْ ‏ ‏يَسْتَهِمُوا ‏ ‏لَاسْتَهَمُوا عَلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f92db8d9-f378-5d93-92c7-199d8e6c4912', '5cb5e738-220a-4267-901a-841c834b5d56', '616', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ حَوْشَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَلَا ‏ ‏تَحْتَسِبُونَ ‏ ‏آثَارَكُمْ ‏ ‏وَقَالَ ‏ ‏مُجَاهِدٌ ‏ ‏فِي قَوْلِهِ ‏ { ‏وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ ‏} ‏قَالَ خُطَاهُمْ ‏ ‏وَقَالَ ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدٌ ‏ ‏حَدَّثَنِي ‏ ‏أَنَسٌ ‏ ‏أَنَّ ‏ ‏بَنِي سَلِمَةَ ‏ ‏أَرَادُوا أَنْ يَتَحَوَّلُوا عَنْ مَنَازِلِهِمْ فَيَنْزِلُوا قَرِيبًا مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَكَرِهَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏يُعْرُوا ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَ أَلَا تَحْتَسِبُونَ ‏ ‏آثَارَكُمْ ‏ ‏قَالَ ‏ ‏مُجَاهِدٌ ‏ ‏خُطَاهُمْ آثَارُهُمْ ‏ ‏أَنْ يُمْشَى فِي الْأَرْضِ بِأَرْجُلِهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('35a78e58-449b-58e1-a0fe-4eca58c6e6f9', '5cb5e738-220a-4267-901a-841c834b5d56', '617', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ صَلَاةٌ أَثْقَلَ عَلَى الْمُنَافِقِينَ مِنْ الْفَجْرِ وَالْعِشَاءِ وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لَأَتَوْهُمَا وَلَوْ حَبْوًا لَقَدْ هَمَمْتُ أَنْ آمُرَ الْمُؤَذِّنَ فَيُقِيمَ ثُمَّ آمُرَ رَجُلًا يَؤُمُّ النَّاسَ ثُمَّ آخُذَ شُعَلًا مِنْ نَارٍ فَأُحَرِّقَ عَلَى مَنْ لَا يَخْرُجُ إِلَى الصَّلَاةِ بَعْدُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3e57b1d9-55de-534f-a722-25bd29b14776', '5cb5e738-220a-4267-901a-841c834b5d56', '618', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا حَضَرَتْ الصَّلَاةُ فَأَذِّنَا وَأَقِيمَا ثُمَّ لِيَؤُمَّكُمَا أَكْبَرُكُمَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3ad3e084-945f-5100-8965-bf06e76741bd', '5cb5e738-220a-4267-901a-841c834b5d56', '619', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَلَائِكَةُ ‏ ‏تُصَلِّي ‏ ‏عَلَى أَحَدِكُمْ مَا دَامَ فِي مُصَلَّاهُ مَا لَمْ ‏ ‏يُحْدِثْ ‏ ‏اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا دَامَتْ الصَّلَاةُ تَحْبِسُهُ لَا يَمْنَعُهُ أَنْ يَنْقَلِبَ إِلَى أَهْلِهِ إِلَّا الصَّلَاةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('882d290a-b95c-5d5a-8938-fcce91f91acc', '5cb5e738-220a-4267-901a-841c834b5d56', '620', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ بُنْدَارٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خُبَيْبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَبْعَةٌ يُظِلُّهُمْ اللَّهُ فِي ظِلِّهِ يَوْمَ لَا ظِلَّ إِلَّا ظِلُّهُ الْإِمَامُ الْعَادِلُ وَشَابٌّ نَشَأَ فِي عِبَادَةِ رَبِّهِ وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسَاجِدِ وَرَجُلَانِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ وَرَجُلٌ ‏ ‏طَلَبَتْهُ ‏ ‏امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ إِنِّي أَخَافُ اللَّهَ وَرَجُلٌ تَصَدَّقَ أَخْفَى حَتَّى لَا تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا ‏ ‏فَفَاضَتْ ‏ ‏عَيْنَاهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('559fbaee-43e0-5341-bdcf-af7bac11a682', '5cb5e738-220a-4267-901a-841c834b5d56', '621', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ سُئِلَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏هَلْ اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا فَقَالَ نَعَمْ أَخَّرَ لَيْلَةً صَلَاةَ الْعِشَاءِ إِلَى ‏ ‏شَطْرِ ‏ ‏اللَّيْلِ ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ بَعْدَ مَا صَلَّى فَقَالَ ‏ ‏صَلَّى النَّاسُ وَرَقَدُوا وَلَمْ تَزَالُوا فِي صَلَاةٍ مُنْذُ انْتَظَرْتُمُوهَا قَالَ فَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏خَاتَمِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('32f3ef04-3787-52e0-8f17-81f43383750b', '5cb5e738-220a-4267-901a-841c834b5d56', '622', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏غَدَا ‏ ‏إِلَى الْمَسْجِدِ ‏ ‏وَرَاحَ ‏ ‏أَعَدَّ اللَّهُ لَهُ ‏ ‏نُزُلَهُ ‏ ‏مِنْ الْجَنَّةِ كُلَّمَا ‏ ‏غَدَا ‏ ‏أَوْ ‏ ‏رَاحَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6458d065-b44f-5178-9364-4c0fbc41192b', '5cb5e738-220a-4267-901a-841c834b5d56', '623', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَالِكٍ ابْنِ بُحَيْنَةَ ‏ ‏قَالَ مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ قَالَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَفْصَ بْنَ عَاصِمٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَجُلًا مِنْ ‏ ‏الْأَزْدِ ‏ ‏يُقَالُ لَهُ ‏ ‏مَالِكُ ابْنُ بُحَيْنَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا وَقَدْ أُقِيمَتْ الصَّلَاةُ ‏ ‏يُصَلِّي رَكْعَتَيْنِ فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَاثَ ‏ ‏بِهِ النَّاسُ وَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ أَرْبَعًا الصُّبْحَ أَرْبَعًا ‏ ‏تَابَعَهُ ‏ ‏غُنْدَرٌ ‏ ‏وَمُعَاذٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏فِي ‏ ‏مَالِكٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏عَنْ ‏ ‏حَفْصٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ابْنِ بُحَيْنَةَ ‏ ‏وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏سَعْدٌ ‏ ‏عَنْ ‏ ‏حَفْصٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0cd4d13b-e0a4-563a-a81e-92e84ffdfaf8', '5cb5e738-220a-4267-901a-841c834b5d56', '624', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَذَكَرْنَا الْمُوَاظَبَةَ عَلَى الصَّلَاةِ وَالتَّعْظِيمَ لَهَا ‏ ‏قَالَتْ ‏ ‏لَمَّا مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَضَهُ الَّذِي مَاتَ فِيهِ فَحَضَرَتْ الصَّلَاةُ فَأُذِّنَ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَقِيلَ لَهُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ ‏ ‏أَسِيفٌ ‏ ‏إِذَا قَامَ فِي مَقَامِكَ لَمْ يَسْتَطِعْ أَنْ يُصَلِّيَ بِالنَّاسِ وَأَعَادَ فَأَعَادُوا لَهُ فَأَعَادَ الثَّالِثَةَ فَقَالَ إِنَّكُنَّ ‏ ‏صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَخَرَجَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَصَلَّى فَوَجَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ نَفْسِهِ خِفَّةً فَخَرَجَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ رَجُلَيْنِ كَأَنِّي أَنْظُرُ رِجْلَيْهِ تَخُطَّانِ مِنْ الْوَجَعِ فَأَرَادَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَنْ يَتَأَخَّرَ فَأَوْمَأَ إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ مَكَانَكَ ثُمَّ أُتِيَ بِهِ حَتَّى جَلَسَ إِلَى جَنْبِهِ قِيلَ ‏ ‏لِلْأَعْمَشِ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏ ‏وَأَبُو بَكْرٍ ‏ ‏يُصَلِّي بِصَلَاتِهِ وَالنَّاسُ يُصَلُّونَ بِصَلَاةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالَ بِرَأْسِهِ نَعَمْ ‏ ‏رَوَاهُ ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بَعْضَهُ ‏ ‏وَزَادَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏جَلَسَ عَنْ يَسَارِ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُصَلِّي قَائِمًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('84695152-51c4-5825-9b81-de99af62f732', '5cb5e738-220a-4267-901a-841c834b5d56', '625', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَمَّا ثَقُلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاشْتَدَّ وَجَعُهُ اسْتَأْذَنَ أَزْوَاجَهُ أَنْ يُمَرَّضَ فِي بَيْتِي فَأَذِنَّ لَهُ فَخَرَجَ بَيْنَ رَجُلَيْنِ تَخُطُّ رِجْلَاهُ الْأَرْضَ وَكَانَ بَيْنَ ‏ ‏الْعَبَّاسِ ‏ ‏وَرَجُلٍ آخَرَ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏مَا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقَالَ لِي وَهَلْ تَدْرِي مَنْ الرَّجُلُ الَّذِي لَمْ تُسَمِّ ‏ ‏عَائِشَةُ ‏ ‏قُلْتُ لَا قَالَ هُوَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9ca9f7cb-e8b8-56b8-8fc8-97e53a75aff9', '5cb5e738-220a-4267-901a-841c834b5d56', '626', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَذَّنَ بِالصَّلَاةِ فِي لَيْلَةٍ ذَاتِ بَرْدٍ وَرِيحٍ ثُمَّ قَالَ أَلَا صَلُّوا فِي الرِّحَالِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْمُرُ الْمُؤَذِّنَ إِذَا كَانَتْ لَيْلَةٌ ذَاتُ بَرْدٍ وَمَطَرٍ يَقُولُ ‏ ‏أَلَا صَلُّوا فِي الرِّحَالِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1d3639bf-358f-5de7-b82c-7482c5f5809a', '5cb5e738-220a-4267-901a-841c834b5d56', '627', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ ‏ ‏أَنَّ ‏ ‏عِتْبَانَ بْنَ مَالِكٍ ‏ ‏كَانَ يَؤُمُّ قَوْمَهُ وَهُوَ أَعْمَى وَأَنَّهُ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّهَا تَكُونُ الظُّلْمَةُ وَالسَّيْلُ وَأَنَا رَجُلٌ ضَرِيرُ الْبَصَرِ فَصَلِّ يَا رَسُولَ اللَّهِ فِي بَيْتِي مَكَانًا أَتَّخِذُهُ مُصَلَّى فَجَاءَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ فَأَشَارَ إِلَى مَكَانٍ مِنْ الْبَيْتِ فَصَلَّى فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('46a75b42-34cd-5ba7-ad7d-282d57c2c127', '5cb5e738-220a-4267-901a-841c834b5d56', '628', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الْوَهَّابِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏صَاحِبُ ‏ ‏الزِّيَادِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الْحَارِثِ ‏ ‏قَالَ خَطَبَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فِي يَوْمٍ ‏ ‏ذِي رَدْغٍ ‏ ‏فَأَمَرَ الْمُؤَذِّنَ لَمَّا بَلَغَ حَيَّ عَلَى الصَّلَاةِ قَالَ قُلْ ‏ ‏الصَّلَاةُ فِي ‏ ‏الرِّحَالِ ‏ ‏فَنَظَرَ بَعْضُهُمْ إِلَى بَعْضٍ فَكَأَنَّهُمْ أَنْكَرُوا فَقَالَ كَأَنَّكُمْ أَنْكَرْتُمْ هَذَا إِنَّ هَذَا فَعَلَهُ مَنْ هُوَ خَيْرٌ مِنِّي ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا عَزْمَةٌ وَإِنِّي كَرِهْتُ أَنْ أُحْرِجَكُمْ ‏ ‏وَعَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏نَحْوَهُ غَيْرَ أَنَّهُ قَالَ كَرِهْتُ أَنْ أُؤَثِّمَكُمْ فَتَجِيئُونَ تَدُوسُونَ الطِّينَ إِلَى رُكَبِكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('af299a0c-df80-5dab-bd0b-92df73924701', '5cb5e738-220a-4267-901a-841c834b5d56', '629', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏فَقَالَ ‏ ‏جَاءَتْ سَحَابَةٌ فَمَطَرَتْ حَتَّى سَالَ السَّقْفُ وَكَانَ مِنْ جَرِيدِ النَّخْلِ فَأُقِيمَتْ الصَّلَاةُ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِي الْمَاءِ وَالطِّينِ حَتَّى رَأَيْتُ أَثَرَ الطِّينِ فِي جَبْهَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('963c1ff6-1648-55bc-9f3e-8474eff3b17a', '5cb5e738-220a-4267-901a-841c834b5d56', '630', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنِّي لَا أَسْتَطِيعُ الصَّلَاةَ مَعَكَ وَكَانَ رَجُلًا ضَخْمًا فَصَنَعَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامًا فَدَعَاهُ إِلَى مَنْزِلِهِ فَبَسَطَ لَهُ حَصِيرًا ‏ ‏وَنَضَحَ ‏ ‏طَرَفَ الْحَصِيرِ ‏ ‏فَصَلَّى عَلَيْهِ رَكْعَتَيْنِ فَقَالَ رَجُلٌ مِنْ آلِ ‏ ‏الْجَارُودِ ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَ مَا رَأَيْتُهُ صَلَّاهَا إِلَّا يَوْمَئِذٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b2a25d4c-011c-5fa0-9ecd-c2356fbb3859', '5cb5e738-220a-4267-901a-841c834b5d56', '631', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا وُضِعَ الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('afbeadb3-4e74-5afe-8111-1305430c5510', '5cb5e738-220a-4267-901a-841c834b5d56', '632', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قُدِّمَ الْعَشَاءُ فَابْدَءُوا بِهِ قَبْلَ أَنْ تُصَلُّوا صَلَاةَ الْمَغْرِبِ وَلَا تَعْجَلُوا عَنْ عَشَائِكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9eeb2861-9a09-5bbf-9a15-5a56fd4ebdb9', '5cb5e738-220a-4267-901a-841c834b5d56', '633', '‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِي أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وُضِعَ عَشَاءُ أَحَدِكُمْ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ وَلَا يَعْجَلْ حَتَّى يَفْرُغَ مِنْهُ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يُوضَعُ لَهُ الطَّعَامُ وَتُقَامُ الصَّلَاةُ فَلَا يَأْتِيهَا حَتَّى يَفْرُغَ وَإِنَّهُ لَيَسْمَعُ قِرَاءَةَ الْإِمَامِ ‏ ‏وَقَالَ ‏ ‏زُهَيْرٌ ‏ ‏وَوَهْبُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ عَلَى الطَّعَامِ فَلَا يَعْجَلْ حَتَّى يَقْضِيَ حَاجَتَهُ مِنْهُ وَإِنْ أُقِيمَتْ الصَّلَاةُ ‏ ‏رَوَاهُ ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ عُثْمَانَ ‏ ‏وَوَهْبٌ ‏ ‏مَدِينِيٌّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5237b937-0839-5348-9a46-c8661b6b0a2d', '5cb5e738-220a-4267-901a-841c834b5d56', '634', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ عَمْرِو بْنِ أُمَيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُ ذِرَاعًا ‏ ‏يَحْتَزُّ ‏ ‏مِنْهَا فَدُعِيَ إِلَى الصَّلَاةِ فَقَامَ فَطَرَحَ السِّكِّينَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('68b1d06d-4ffb-5228-ae54-24bda5c83df2', '5cb5e738-220a-4267-901a-841c834b5d56', '635', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ فِي بَيْتِهِ قَالَتْ كَانَ ‏ ‏يَكُونُ فِي مِهْنَةِ أَهْلِهِ ‏ ‏تَعْنِي خِدْمَةَ أَهْلِهِ ‏ ‏فَإِذَا حَضَرَتْ الصَّلَاةُ خَرَجَ إِلَى الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('62d238ae-7a53-586a-b590-1d1d5db874da', '5cb5e738-220a-4267-901a-841c834b5d56', '636', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ جَاءَنَا ‏ ‏مَالِكُ بْنُ الْحُوَيْرِثِ ‏ ‏فِي مَسْجِدِنَا هَذَا ‏ ‏فَقَالَ ‏ ‏إِنِّي لَأُصَلِّي بِكُمْ وَمَا أُرِيدُ الصَّلَاةَ أُصَلِّي كَيْفَ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَقُلْتُ ‏ ‏لِأَبِي قِلَابَةَ ‏ ‏كَيْفَ كَانَ ‏ ‏يُصَلِّي قَالَ مِثْلَ شَيْخِنَا هَذَا قَالَ وَكَانَ شَيْخًا يَجْلِسُ إِذَا رَفَعَ رَأْسَهُ مِنْ السُّجُودِ قَبْلَ أَنْ يَنْهَضَ فِي الرَّكْعَةِ الْأُولَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f2c83a4c-e3f6-5679-a2fb-93e72fda7180', '5cb5e738-220a-4267-901a-841c834b5d56', '637', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ نَصْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏مَرِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاشْتَدَّ مَرَضُهُ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّهُ رَجُلٌ رَقِيقٌ إِذَا قَامَ مَقَامَكَ لَمْ يَسْتَطِعْ أَنْ يُصَلِّيَ بِالنَّاسِ قَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَعَادَتْ فَقَالَ مُرِي ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَإِنَّكُنَّ ‏ ‏صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏فَأَتَاهُ الرَّسُولُ فَصَلَّى بِالنَّاسِ فِي حَيَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a8fd8093-cbb6-5019-9138-f05ca342eab1', '5cb5e738-220a-4267-901a-841c834b5d56', '638', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي مَرَضِهِ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قُلْتُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعْ النَّاسَ مِنْ الْبُكَاءِ فَمُرْ ‏ ‏عُمَرَ ‏ ‏فَلْيُصَلِّ لِلنَّاسِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ ‏ ‏لِحَفْصَةَ ‏ ‏قُولِي لَهُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعْ النَّاسَ مِنْ الْبُكَاءِ فَمُرْ ‏ ‏عُمَرَ ‏ ‏فَلْيُصَلِّ لِلنَّاسِ فَفَعَلَتْ ‏ ‏حَفْصَةُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْ ‏ ‏إِنَّكُنَّ لَأَنْتُنَّ ‏ ‏صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ لِلنَّاسِ فَقَالَتْ ‏ ‏حَفْصَةُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا كُنْتُ لِأُصِيبَ مِنْكِ خَيْرًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b80b5c18-8f17-5162-a164-9c6385e1b773', '5cb5e738-220a-4267-901a-841c834b5d56', '639', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ الْأَنْصَارِيُّ ‏ ‏وَكَانَ تَبِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَدَمَهُ وَصَحِبَهُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ ‏ ‏يُصَلِّي لَهُمْ فِي وَجَعِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي تُوُفِّيَ فِيهِ حَتَّى إِذَا كَانَ يَوْمُ ‏ ‏الِاثْنَيْنِ وَهُمْ صُفُوفٌ فِي الصَّلَاةِ فَكَشَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِتْرَ الْحُجْرَةِ يَنْظُرُ إِلَيْنَا وَهُوَ قَائِمٌ كَأَنَّ وَجْهَهُ وَرَقَةُ مُصْحَفٍ ثُمَّ تَبَسَّمَ يَضْحَكُ فَهَمَمْنَا أَنْ نَفْتَتِنَ مِنْ الْفَرَحِ بِرُؤْيَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَكَصَ ‏ ‏أَبُو بَكْرٍ ‏ ‏عَلَى عَقِبَيْهِ لِيَصِلَ الصَّفَّ وَظَنَّ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَارِجٌ إِلَى الصَّلَاةِ ‏ ‏فَأَشَارَ إِلَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أَتِمُّوا صَلَاتَكُمْ وَأَرْخَى السِّتْرَ فَتُوُفِّيَ مِنْ يَوْمِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0b000e3f-bf72-5ca7-9958-829a4bfad73f', '5cb5e738-220a-4267-901a-841c834b5d56', '640', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمْ يَخْرُجْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثًا فَأُقِيمَتْ الصَّلَاةُ فَذَهَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَتَقَدَّمُ فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحِجَابِ فَرَفَعَهُ فَلَمَّا وَضَحَ وَجْهُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَظَرْنَا مَنْظَرًا كَانَ أَعْجَبَ إِلَيْنَا مِنْ وَجْهِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ وَضَحَ لَنَا ‏ ‏فَأَوْمَأَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏أَنْ يَتَقَدَّمَ وَأَرْخَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحِجَابَ فَلَمْ يُقْدَرْ عَلَيْهِ حَتَّى مَاتَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1799a949-f665-5d12-9aa9-f720b31f21f4', '5cb5e738-220a-4267-901a-841c834b5d56', '641', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏لَمَّا اشْتَدَّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَعُهُ قِيلَ لَهُ فِي الصَّلَاةِ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ رَقِيقٌ إِذَا قَرَأَ غَلَبَهُ الْبُكَاءُ قَالَ مُرُوهُ فَيُصَلِّي فَعَاوَدَتْهُ قَالَ مُرُوهُ فَيُصَلِّي إِنَّكُنَّ ‏ ‏صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏تَابَعَهُ ‏ ‏الزُّبَيْدِيُّ ‏ ‏وَابْنُ أَخِي الزُّهْرِيِّ ‏ ‏وَإِسْحَاقُ بْنُ يَحْيَى الْكَلْبِيُّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏وَقَالَ ‏ ‏عُقَيْلٌ ‏ ‏وَمَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9f469f6f-51a0-53fc-baaa-e764d9d9cf0c', '5cb5e738-220a-4267-901a-841c834b5d56', '642', '‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّاءُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يُصَلِّيَ بِالنَّاسِ فِي مَرَضِهِ فَكَانَ ‏ ‏يُصَلِّي بِهِمْ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏فَوَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَفْسِهِ خِفَّةً فَخَرَجَ فَإِذَا ‏ ‏أَبُو بَكْرٍ ‏ ‏يَؤُمُّ النَّاسَ فَلَمَّا رَآهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏اسْتَأْخَرَ فَأَشَارَ إِلَيْهِ أَنْ كَمَا أَنْتَ فَجَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِذَاءَ ‏ ‏أَبِي بَكْرٍ ‏ ‏إِلَى جَنْبِهِ فَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُصَلِّي بِصَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ يُصَلُّونَ بِصَلَاةِ ‏ ‏أَبِي بَكْرٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6acc9e19-2931-5f0e-8a52-a45e6c64c4ac', '5cb5e738-220a-4267-901a-841c834b5d56', '643', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَهَبَ إِلَى ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏لِيُصْلِحَ بَيْنَهُمْ ‏ ‏فَحَانَتْ ‏ ‏الصَّلَاةُ فَجَاءَ الْمُؤَذِّنُ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالَ أَتُصَلِّي لِلنَّاسِ فَأُقِيمَ قَالَ نَعَمْ فَصَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ فِي الصَّلَاةِ ‏ ‏فَتَخَلَّصَ ‏ ‏حَتَّى وَقَفَ فِي الصَّفِّ فَصَفَّقَ النَّاسُ وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏لَا يَلْتَفِتُ فِي صَلَاتِهِ فَلَمَّا أَكْثَرَ النَّاسُ التَّصْفِيقَ الْتَفَتَ فَرَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَشَارَ إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ امْكُثْ مَكَانَكَ فَرَفَعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَدَيْهِ فَحَمِدَ اللَّهَ عَلَى مَا أَمَرَهُ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ذَلِكَ ثُمَّ اسْتَأْخَرَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَتَّى اسْتَوَى فِي الصَّفِّ وَتَقَدَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى فَلَمَّا انْصَرَفَ قَالَ ‏ ‏يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏مَا مَنَعَكَ أَنْ تَثْبُتَ إِذْ أَمَرْتُكَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَا كَانَ ‏ ‏لِابْنِ أَبِي قُحَافَةَ ‏ ‏أَنْ يُصَلِّيَ ‏ ‏بَيْنَ يَدَيْ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لِي رَأَيْتُكُمْ أَكْثَرْتُمْ التَّصْفِيقَ مَنْ ‏ ‏رَابَهُ ‏ ‏شَيْءٌ فِي صَلَاتِهِ فَلْيُسَبِّحْ فَإِنَّهُ إِذَا سَبَّحَ الْتُفِتَ إِلَيْهِ وَإِنَّمَا التَّصْفِيقُ لِلنِّسَاءِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8e8162f0-dde8-5551-b3fd-b5a9535f512a', '5cb5e738-220a-4267-901a-841c834b5d56', '644', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏قَالَ ‏ ‏قَدِمْنَا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ شَبَبَةٌ فَلَبِثْنَا عِنْدَهُ نَحْوًا مِنْ عِشْرِينَ لَيْلَةً وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِيمًا فَقَالَ ‏ ‏لَوْ رَجَعْتُمْ إِلَى بِلَادِكُمْ فَعَلَّمْتُمُوهُمْ مُرُوهُمْ فَلْيُصَلُّوا صَلَاةَ كَذَا فِي حِينِ كَذَا وَصَلَاةَ كَذَا فِي حِينِ كَذَا وَإِذَا حَضَرَتْ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c8f0266a-a3e8-50ec-82d1-1aa1fee34ebe', '5cb5e738-220a-4267-901a-841c834b5d56', '645', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ أَسَدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَحْمُودُ بْنُ الرَّبِيعِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عِتْبَانَ بْنَ مَالِكٍ الْأَنْصارِيَّ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَذِنْتُ لَهُ فَقَالَ ‏ ‏أَيْنَ تُحِبُّ أَنْ أُصَلِّيَ مِنْ بَيْتِكَ فَأَشَرْتُ لَهُ إِلَى الْمَكَانِ الَّذِي أُحِبُّ فَقَامَ وَصَفَفْنَا خَلْفَهُ ثُمَّ سَلَّمَ وَسَلَّمْنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b4cada6f-4d79-563f-ad25-2cc5ff8e29e8', '5cb5e738-220a-4267-901a-841c834b5d56', '646', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ ‏ ‏أَلَا تُحَدِّثِينِي عَنْ مَرَضِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ بَلَى ‏ ‏ثَقُلَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَصَلَّى النَّاسُ قُلْنَا لَا هُمْ يَنْتَظِرُونَكَ قَالَ ضَعُوا لِي مَاءً فِي ‏ ‏الْمِخْضَبِ ‏ ‏قَالَتْ فَفَعَلْنَا فَاغْتَسَلَ فَذَهَبَ ‏ ‏لِيَنُوءَ ‏ ‏فَأُغْمِيَ عَلَيْهِ ثُمَّ أَفَاقَ فَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَلَّى النَّاسُ قُلْنَا لَا هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ قَالَ ضَعُوا لِي مَاءً فِي ‏ ‏الْمِخْضَبِ ‏ ‏قَالَتْ فَقَعَدَ فَاغْتَسَلَ ثُمَّ ذَهَبَ ‏ ‏لِيَنُوءَ ‏ ‏فَأُغْمِيَ عَلَيْهِ ثُمَّ أَفَاقَ فَقَالَ أَصَلَّى النَّاسُ قُلْنَا لَا هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ فَقَالَ ضَعُوا لِي مَاءً فِي ‏ ‏الْمِخْضَبِ ‏ ‏فَقَعَدَ فَاغْتَسَلَ ثُمَّ ذَهَبَ ‏ ‏لِيَنُوءَ ‏ ‏فَأُغْمِيَ عَلَيْهِ ثُمَّ أَفَاقَ فَقَالَ أَصَلَّى النَّاسُ فَقُلْنَا لَا هُمْ يَنْتَظِرُونَكَ يَا رَسُولَ اللَّهِ وَالنَّاسُ ‏ ‏عُكُوفٌ ‏ ‏فِي الْمَسْجِدِ يَنْتَظِرُونَ النَّبِيَّ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏لِصَلَاةِ الْعِشَاءِ الْآخِرَةِ فَأَرْسَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏بِأَنْ يُصَلِّيَ بِالنَّاسِ فَأَتَاهُ الرَّسُولُ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُكَ أَنْ تُصَلِّيَ بِالنَّاسِ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَكَانَ رَجُلًا رَقِيقًا يَا ‏ ‏عُمَرُ ‏ ‏صَلِّ بِالنَّاسِ فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏أَنْتَ أَحَقُّ بِذَلِكَ فَصَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏تِلْكَ الْأَيَّامَ ثُمَّ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ مِنْ نَفْسِهِ خِفَّةً فَخَرَجَ بَيْنَ رَجُلَيْنِ أَحَدُهُمَا ‏ ‏الْعَبَّاسُ ‏ ‏لِصَلَاةِ الظُّهْرِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ فَلَمَّا رَآهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏ذَهَبَ لِيَتَأَخَّرَ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَنْ لَا يَتَأَخَّرَ قَالَ أَجْلِسَانِي إِلَى جَنْبِهِ فَأَجْلَسَاهُ إِلَى جَنْبِ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ فَجَعَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُصَلِّي وَهُوَ يَأْتَمُّ بِصَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ بِصَلَاةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدٌ ‏ ‏قَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏فَقُلْتُ لَهُ أَلَا أَعْرِضُ عَلَيْكَ مَا حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏عَنْ مَرَضِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَاتِ فَعَرَضْتُ عَلَيْهِ حَدِيثَهَا فَمَا أَنْكَرَ مِنْهُ شَيْئًا غَيْرَ أَنَّهُ قَالَ أَسَمَّتْ لَكَ الرَّجُلَ الَّذِي كَانَ مَعَ ‏ ‏الْعَبَّاسِ ‏ ‏قُلْتُ لَا قَالَ هُوَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e4a97034-e13c-53fa-8c77-3c5290f18ca5', '5cb5e738-220a-4267-901a-841c834b5d56', '647', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ وَهُوَ شَاكٍ فَصَلَّى جَالِسًا وَصَلَّى وَرَاءَهُ قَوْمٌ قِيَامًا فَأَشَارَ إِلَيْهِمْ أَنْ اجْلِسُوا فَلَمَّا انْصَرَفَ قَالَ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7d8f74d5-85b1-53dd-8a09-e0ab65cc095f', '5cb5e738-220a-4267-901a-841c834b5d56', '648', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكِبَ فَرَسًا ‏ ‏فَصُرِعَ ‏ ‏عَنْهُ ‏ ‏فَجُحِشَ ‏ ‏شِقُّهُ الْأَيْمَنُ فَصَلَّى صَلَاةً مِنْ الصَّلَوَاتِ وَهُوَ قَاعِدٌ فَصَلَّيْنَا وَرَاءَهُ قُعُودًا فَلَمَّا انْصَرَفَ قَالَ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا صَلَّى قَائِمًا فَصَلُّوا قِيَامًا فَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ وَإِذَا صَلَّى قَائِمًا فَصَلُّوا قِيَامًا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏الْحُمَيْدِيُّ ‏ ‏قَوْلُهُ ‏ ‏إِذَا صَلَّى جَالِسًا ‏ ‏فَصَلُّوا جُلُوسًا هُوَ فِي مَرَضِهِ الْقَدِيمِ ثُمَّ صَلَّى بَعْدَ ذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا وَالنَّاسُ خَلْفَهُ قِيَامًا لَمْ يَأْمُرْهُمْ بِالْقُعُودِ وَإِنَّمَا يُؤْخَذُ بِالْآخِرِ فَالْآخِرِ مِنْ فِعْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a961a50c-273b-5479-87de-85db04b27b07', '5cb5e738-220a-4267-901a-841c834b5d56', '649', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْبَرَاءُ ‏ ‏وَهُوَ غَيْرُ كَذُوبٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ لَمْ يَحْنِ أَحَدٌ مِنَّا ظَهْرَهُ حَتَّى يَقَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاجِدًا ثُمَّ نَقَعُ سُجُودًا بَعْدَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏نَحْوَهُ بِهَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('220e3604-6b9e-54d6-89a8-f37095ab79c7', '5cb5e738-220a-4267-901a-841c834b5d56', '650', '‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَمَا يَخْشَى أَحَدُكُمْ أَوْ لَا يَخْشَى أَحَدُكُمْ إِذَا رَفَعَ رَأْسَهُ قَبْلَ الْإِمَامِ أَنْ يَجْعَلَ اللَّهُ رَأْسَهُ رَأْسَ حِمَارٍ أَوْ يَجْعَلَ اللَّهُ صُورَتَهُ صُورَةَ حِمَارٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9f51e890-1380-5fa5-a3a2-01fa0125345d', '5cb5e738-220a-4267-901a-841c834b5d56', '651', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏الْمُهَاجِرُونَ الْأَوَّلُونَ ‏ ‏الْعُصْبَةَ ‏ ‏مَوْضِعٌ ‏ ‏بِقُبَاءٍ ‏ ‏قَبْلَ مَقْدَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَؤُمُّهُمْ ‏ ‏سَالِمٌ ‏ ‏مَوْلَى ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏وَكَانَ أَكْثَرَهُمْ قُرْآنًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4005f127-635f-56f4-817f-44faf1ec8682', '5cb5e738-220a-4267-901a-841c834b5d56', '652', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْمَعُوا وَأَطِيعُوا وَإِنْ اسْتُعْمِلَ حَبَشِيٌّ كَأَنَّ رَأْسَهُ زَبِيبَةٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c9807c23-1315-5589-9eaa-39f7bfbf78d7', '5cb5e738-220a-4267-901a-841c834b5d56', '653', '‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ سَهْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى الْأَشْيَبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُصَلُّونَ لَكُمْ فَإِنْ أَصَابُوا فَلَكُمْ وَإِنْ أَخْطَئُوا فَلَكُمْ وَعَلَيْهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('946c04cd-87f9-5a82-98a6-5c12ddb651d8', '5cb5e738-220a-4267-901a-841c834b5d56', '654', '‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏وَقَالَ لَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ خِيَارٍ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏عُثْمَانَ بْنِ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ ‏ ‏مَحْصُورٌ ‏ ‏فَقَالَ إِنَّكَ إِمَامُ عَامَّةٍ وَنَزَلَ بِكَ مَا نَرَى وَيُصَلِّي لَنَا إِمَامُ فِتْنَةٍ وَنَتَحَرَّجُ فَقَالَ ‏ ‏الصَّلَاةُ أَحْسَنُ مَا يَعْمَلُ النَّاسُ فَإِذَا أَحْسَنَ النَّاسُ فَأَحْسِنْ مَعَهُمْ وَإِذَا أَسَاءُوا فَاجْتَنِبْ إِسَاءَتَهُمْ ‏ ‏وَقَالَ ‏ ‏الزُّبَيْدِيُّ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏لَا نَرَى أَنْ يُصَلَّى خَلْفَ ‏ ‏الْمُخَنَّثِ ‏ ‏إِلَّا مِنْ ضَرُورَةٍ لَا بُدَّ مِنْهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b44a3022-a33a-5d76-8480-70debecbe10b', '5cb5e738-220a-4267-901a-841c834b5d56', '655', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَبِي ذَرٍّ ‏ ‏اسْمَعْ وَأَطِعْ وَلَوْ لِحَبَشِيٍّ كَأَنَّ رَأْسَهُ زَبِيبَةٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bca7c2ea-4cac-5d81-89d5-07942878fd7b', '5cb5e738-220a-4267-901a-841c834b5d56', '656', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏بِتُّ فِي بَيْتِ خَالَتِي ‏ ‏مَيْمُونَةَ ‏ ‏فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ ثُمَّ جَاءَ فَصَلَّى أَرْبَعَ رَكَعَاتٍ ثُمَّ نَامَ ثُمَّ قَامَ فَجِئْتُ فَقُمْتُ عَنْ يَسَارِهِ فَجَعَلَنِي عَنْ يَمِينِهِ فَصَلَّى خَمْسَ رَكَعَاتٍ ثُمَّ صَلَّى رَكْعَتَيْنِ ثُمَّ نَامَ حَتَّى سَمِعْتُ ‏ ‏غَطِيطَهُ ‏ ‏أَوْ قَالَ ‏ ‏خَطِيطَهُ ‏ ‏ثُمَّ خَرَجَ إِلَى الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0ddbb680-a5a7-5a18-ba1e-1747e28b1950', '5cb5e738-220a-4267-901a-841c834b5d56', '657', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مَخْرَمَةَ بْنِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏نِمْتُ عِنْدَ ‏ ‏مَيْمُونَةَ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَهَا تِلْكَ اللَّيْلَةَ ‏ ‏فَتَوَضَّأَ ثُمَّ قَامَ ‏ ‏يُصَلِّي فَقُمْتُ عَلَى يَسَارِهِ فَأَخَذَنِي فَجَعَلَنِي عَنْ يَمِينِهِ فَصَلَّى ثَلَاثَ عَشْرَةَ رَكْعَةً ثُمَّ نَامَ حَتَّى نَفَخَ وَكَانَ إِذَا نَامَ نَفَخَ ثُمَّ أَتَاهُ الْمُؤَذِّنُ فَخَرَجَ فَصَلَّى وَلَمْ يَتَوَضَّأْ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏بُكَيْرًا ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏كُرَيْبٌ ‏ ‏بِذَلِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6e44d4a-fc1a-55f1-a944-d022b5560973', '5cb5e738-220a-4267-901a-841c834b5d56', '658', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بِتُّ عِنْدَ ‏ ‏خَالَتِي ‏ ‏فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فَقُمْتُ أُصَلِّي مَعَهُ فَقُمْتُ عَنْ يَسَارِهِ فَأَخَذَ بِرَأْسِي فَأَقَامَنِي عَنْ يَمِينِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81d3a425-6305-5dbc-b0d6-4ecb627d673a', '5cb5e738-220a-4267-901a-841c834b5d56', '659', '‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏مُعَاذَ بْنَ جَبَلٍ ‏ ‏كَانَ ‏ ‏يُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَرْجِعُ فَيَؤُمُّ قَوْمَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e3d8c362-cb22-55b1-89bf-30408cc5c41e', '5cb5e738-220a-4267-901a-841c834b5d56', '660', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏يُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَرْجِعُ فَيَؤُمُّ قَوْمَهُ فَصَلَّى الْعِشَاءَ فَقَرَأَ ‏ ‏بِالْبَقَرَةِ ‏ ‏فَانْصَرَفَ الرَّجُلُ فَكَأَنَّ ‏ ‏مُعَاذًا ‏ ‏تَنَاوَلَ مِنْهُ ‏ ‏فَبَلَغَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ فَتَّانٌ فَتَّانٌ فَتَّانٌ ثَلَاثَ مِرَارٍ ‏ ‏أَوْ قَالَ فَاتِنًا فَاتِنًا فَاتِنًا ‏ ‏وَأَمَرَهُ بِسُورَتَيْنِ مِنْ أَوْسَطِ ‏ ‏الْمُفَصَّلِ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏لَا أَحْفَظُهُمَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9bfec6d5-992a-55ce-8e0e-5d97baccad33', '5cb5e738-220a-4267-901a-841c834b5d56', '661', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَيْسًا ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو مَسْعُودٍ ‏ ‏أَنَّ رَجُلًا قَالَ وَاللَّهِ يَا رَسُولَ اللَّهِ إِنِّي لَأَتَأَخَّرُ عَنْ ‏ ‏صَلَاةِ الْغَدَاةِ ‏ ‏مِنْ أَجْلِ فُلَانٍ مِمَّا يُطِيلُ بِنَا فَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَوْعِظَةٍ أَشَدَّ غَضَبًا مِنْهُ يَوْمَئِذٍ ثُمَّ قَالَ ‏ ‏إِنَّ مِنْكُمْ مُنَفِّرِينَ فَأَيُّكُمْ مَا صَلَّى بِالنَّاسِ ‏ ‏فَلْيَتَجَوَّزْ ‏ ‏فَإِنَّ فِيهِمْ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9d58ae3d-759d-5d3c-8250-4f0c461af87c', '5cb5e738-220a-4267-901a-841c834b5d56', '662', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ لِلنَّاسِ فَلْيُخَفِّفْ فَإِنَّ مِنْهُمْ الضَّعِيفَ ‏ ‏وَالسَّقِيمَ ‏ ‏وَالْكَبِيرَ وَإِذَا صَلَّى أَحَدُكُمْ لِنَفْسِهِ فَلْيُطَوِّلْ مَا شَاءَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0a7c3547-30f2-5914-8b20-ecf57e010836', '5cb5e738-220a-4267-901a-841c834b5d56', '663', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ إِنِّي لَأَتَأَخَّرُ عَنْ الصَّلَاةِ فِي الْفَجْرِ مِمَّا يُطِيلُ بِنَا فُلَانٌ فِيهَا فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا رَأَيْتُهُ غَضِبَ فِي مَوْضِعٍ كَانَ أَشَدَّ غَضَبًا مِنْهُ يَوْمَئِذٍ ثُمَّ قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ مِنْكُمْ مُنَفِّرِينَ فَمَنْ أَمَّ النَّاسَ ‏ ‏فَلْيَتَجَوَّزْ ‏ ‏فَإِنَّ خَلْفَهُ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4862cc1e-7633-5fa4-8272-896ccc5afee0', '5cb5e738-220a-4267-901a-841c834b5d56', '664', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ بْنُ أَبِي إِيَاسٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَارِبُ بْنُ دِثَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏قَالَ ‏ ‏أَقْبَلَ رَجُلٌ ‏ ‏بِنَاضِحَيْنِ ‏ ‏وَقَدْ ‏ ‏جَنَحَ اللَّيْلُ ‏ ‏فَوَافَقَ ‏ ‏مُعَاذًا ‏ ‏يُصَلِّي فَتَرَكَ ‏ ‏نَاضِحَهُ ‏ ‏وَأَقْبَلَ إِلَى ‏ ‏مُعَاذٍ ‏ ‏فَقَرَأَ بِسُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏أَوْ ‏ ‏النِّسَاءِ ‏ ‏فَانْطَلَقَ الرَّجُلُ وَبَلَغَهُ أَنَّ ‏ ‏مُعَاذًا ‏ ‏نَالَ مِنْهُ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَكَا إِلَيْهِ ‏ ‏مُعَاذًا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏مُعَاذُ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ ‏ ‏أَوْ أَفَاتِنٌ ‏ ‏ثَلَاثَ مِرَارٍ فَلَوْلَا صَلَّيْتَ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ ‏ ‏وَالشَّمْسِ وَضُحَاهَا ‏ ‏وَاللَّيْلِ إِذَا يَغْشَى ‏ ‏فَإِنَّهُ ‏ ‏يُصَلِّي وَرَاءَكَ الْكَبِيرُ وَالضَّعِيفُ وَذُو الْحَاجَةِ ‏ ‏أَحْسِبُ ‏ ‏هَذَا فِي الْحَدِيثِ ‏ ‏قَالَ أَبُو عَبْد اللَّهِ ‏ ‏وَتَابَعَهُ ‏ ‏سَعِيدُ بْنُ مَسْرُوقٍ ‏ ‏وَمِسْعَرٌ ‏ ‏وَالشَّيْبَانِيُّ ‏ ‏قَالَ ‏ ‏عَمْرٌو ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ مِقْسَمٍ ‏ ‏وَأَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَرَأَ ‏ ‏مُعَاذٌ ‏ ‏فِي الْعِشَاءِ ‏ ‏بِالْبَقَرَةِ ‏ ‏وَتَابَعَهُ ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏مُحَارِبٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cdaeb1b5-878d-55d4-9fed-27a8b6f9d3e9', '5cb5e738-220a-4267-901a-841c834b5d56', '665', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوجِزُ الصَّلَاةَ وَيُكْمِلُهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bde183a6-dd27-5c04-87d9-3c3eb57087cb', '5cb5e738-220a-4267-901a-841c834b5d56', '666', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَقُومُ فِي الصَّلَاةِ أُرِيدُ أَنْ أُطَوِّلَ فِيهَا فَأَسْمَعُ بُكَاءَ الصَّبِيِّ ‏ ‏فَأَتَجَوَّزُ ‏ ‏فِي صَلَاتِي كَرَاهِيَةَ أَنْ أَشُقَّ عَلَى أُمِّهِ ‏ ‏تَابَعَهُ ‏ ‏بِشْرُ بْنُ بَكْرٍ ‏ ‏وَابْنُ الْمُبَارَكِ ‏ ‏وَبَقِيَّةُ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('75262a7a-10ea-51ca-80b7-b930994acdda', '5cb5e738-220a-4267-901a-841c834b5d56', '667', '‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا صَلَّيْتُ وَرَاءَ إِمَامٍ قَطُّ أَخَفَّ صَلَاةً وَلَا أَتَمَّ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنْ كَانَ لَيَسْمَعُ بُكَاءَ الصَّبِيِّ فَيُخَفِّفُ مَخَافَةَ أَنْ ‏ ‏تُفْتَنَ ‏ ‏أُمُّهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bc534711-4eea-5770-ad84-11e186d37453', '5cb5e738-220a-4267-901a-841c834b5d56', '668', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَدْخُلُ فِي الصَّلَاةِ وَأَنَا أُرِيدُ إِطَالَتَهَا فَأَسْمَعُ بُكَاءَ الصَّبِيِّ ‏ ‏فَأَتَجَوَّزُ ‏ ‏فِي صَلَاتِي مِمَّا أَعْلَمُ مِنْ شِدَّةِ ‏ ‏وَجْدِ ‏ ‏أُمِّهِ مِنْ بُكَائِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a98e2972-ad53-546f-a35e-ac87937886ca', '5cb5e738-220a-4267-901a-841c834b5d56', '669', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَدْخُلُ فِي الصَّلَاةِ فَأُرِيدُ إِطَالَتَهَا فَأَسْمَعُ بُكَاءَ الصَّبِيِّ ‏ ‏فَأَتَجَوَّزُ ‏ ‏مِمَّا أَعْلَمُ مِنْ شِدَّةِ ‏ ‏وَجْدِ ‏ ‏أُمِّهِ مِنْ بُكَائِهِ ‏ ‏وَقَالَ ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('03d943a1-54da-5ded-b653-a5406c77e78a', '5cb5e738-220a-4267-901a-841c834b5d56', '670', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏وَأَبُو النُّعْمَانِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاذٌ ‏ ‏يُصَلِّي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَأْتِي قَوْمَهُ فَيُصَلِّي بِهِمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('22b0c9ac-4ead-5c64-a198-510e715644ff', '5cb5e738-220a-4267-901a-841c834b5d56', '671', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏لَمَّا مَرِضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَضَهُ الَّذِي مَاتَ فِيهِ أَتَاهُ ‏ ‏بِلَالٌ ‏ ‏يُوذِنُهُ بِالصَّلَاةِ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ قُلْتُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ ‏ ‏أَسِيفٌ ‏ ‏إِنْ يَقُمْ مَقَامَكَ يَبْكِي فَلَا يَقْدِرُ عَلَى الْقِرَاءَةِ فَقَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ فَقُلْتُ مِثْلَهُ فَقَالَ فِي الثَّالِثَةِ أَوْ الرَّابِعَةِ إِنَّكُنَّ ‏ ‏صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ فَصَلَّى وَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ رَجُلَيْنِ كَأَنِّي أَنْظُرُ إِلَيْهِ ‏ ‏يَخُطُّ ‏ ‏بِرِجْلَيْهِ الْأَرْضَ فَلَمَّا رَآهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏ذَهَبَ يَتَأَخَّرُ فَأَشَارَ إِلَيْهِ أَنْ صَلِّ فَتَأَخَّرَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَقَعَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى جَنْبِهِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏يُسْمِعُ النَّاسَ التَّكْبِيرَ ‏ ‏تَابَعَهُ ‏ ‏مُحَاضِرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('06de001e-ec89-5b09-ad72-9675316e2854', '5cb5e738-220a-4267-901a-841c834b5d56', '672', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا ‏ ‏ثَقُلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ‏ ‏بِلَالٌ ‏ ‏يُوذِنُهُ بِالصَّلَاةِ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يُصَلِّيَ بِالنَّاسِ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ ‏ ‏أَسِيفٌ ‏ ‏وَإِنَّهُ مَتَى مَا يَقُمْ مَقَامَكَ لَا يُسْمِعُ النَّاسَ فَلَوْ أَمَرْتَ ‏ ‏عُمَرَ ‏ ‏فَقَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ فَقُلْتُ ‏ ‏لِحَفْصَةَ ‏ ‏قُولِي لَهُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ ‏ ‏أَسِيفٌ ‏ ‏وَإِنَّهُ مَتَى يَقُمْ مَقَامَكَ لَا يُسْمِعُ النَّاسَ فَلَوْ أَمَرْتَ ‏ ‏عُمَرَ ‏ ‏قَالَ إِنَّكُنَّ لَأَنْتُنَّ ‏ ‏صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يُصَلِّيَ بِالنَّاسِ فَلَمَّا دَخَلَ فِي الصَّلَاةِ وَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَفْسِهِ خِفَّةً فَقَامَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ رَجُلَيْنِ وَرِجْلَاهُ ‏ ‏يَخُطَّانِ ‏ ‏فِي الْأَرْضِ حَتَّى دَخَلَ الْمَسْجِدَ فَلَمَّا سَمِعَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حِسَّهُ ذَهَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَتَأَخَّرُ ‏ ‏فَأَوْمَأَ ‏ ‏إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى جَلَسَ عَنْ يَسَارِ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُصَلِّي قَائِمًا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَاعِدًا يَقْتَدِي ‏ ‏أَبُو بَكْرٍ ‏ ‏بِصَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسُ مُقْتَدُونَ بِصَلَاةِ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('89b7ea70-5d46-5249-b277-f1e45852918a', '5cb5e738-220a-4267-901a-841c834b5d56', '673', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ أَبِي تَمِيمَةَ السَّخْتِيَانِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْصَرَفَ مِنْ اثْنَتَيْنِ فَقَالَ لَهُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏أَقَصُرَتْ الصَّلَاةُ أَمْ نَسِيتَ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَدَقَ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏فَقَالَ النَّاسُ نَعَمْ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى اثْنَتَيْنِ أُخْرَيَيْنِ ثُمَّ سَلَّمَ ثُمَّ كَبَّرَ فَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5ee0e7ed-9f87-5b47-83b3-d48c0a0028e2', '5cb5e738-220a-4267-901a-841c834b5d56', '674', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ رَكْعَتَيْنِ فَقِيلَ صَلَّيْتَ رَكْعَتَيْنِ فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ سَجَدَ سَجْدَتَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04ff1052-6239-5a9f-9815-24aa4029ef6a', '5cb5e738-220a-4267-901a-841c834b5d56', '675', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي مَرَضِهِ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قُلْتُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعْ النَّاسَ مِنْ الْبُكَاءِ فَمُرْ ‏ ‏عُمَرَ ‏ ‏فَلْيُصَلِّ فَقَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ لِلنَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لِحَفْصَةَ ‏ ‏قُولِي لَهُ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏إِذَا قَامَ فِي مَقَامِكَ لَمْ يُسْمِعْ النَّاسَ مِنْ الْبُكَاءِ فَمُرْ ‏ ‏عُمَرَ ‏ ‏فَلْيُصَلِّ لِلنَّاسِ فَفَعَلَتْ ‏ ‏حَفْصَةُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَهْ ‏ ‏إِنَّكُنَّ لَأَنْتُنَّ ‏ ‏صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ لِلنَّاسِ قَالَتْ ‏ ‏حَفْصَةُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا كُنْتُ لِأُصِيبَ مِنْكِ خَيْرًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3c2f1465-fca5-5f72-9869-9091c7e177fc', '5cb5e738-220a-4267-901a-841c834b5d56', '676', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَالِمَ بْنَ أَبِي الْجَعْدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏يَقُولُ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَتُسَوُّنَّ صُفُوفَكُمْ أَوْ لَيُخَالِفَنَّ اللَّهُ بَيْنَ وُجُوهِكُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e662ec9e-3e55-5445-b201-c689c0471e0c', '5cb5e738-220a-4267-901a-841c834b5d56', '677', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِيمُوا الصُّفُوفَ فَإِنِّي أَرَاكُمْ خَلْفَ ظَهْرِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6807fc2f-16b5-5825-bb00-76c045e464cd', '5cb5e738-220a-4267-901a-841c834b5d56', '678', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ ابْنُ أَبِي رَجَاءٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ بْنُ قُدَامَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ فَأَقْبَلَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِوَجْهِهِ فَقَالَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ ‏ ‏وَتَرَاصُّوا ‏ ‏فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('792c705f-5c0e-5bbb-b79f-427d8cc094d1', '5cb5e738-220a-4267-901a-841c834b5d56', '679', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشُّهَدَاءُ ‏ ‏الْغَرِقُ ‏ ‏وَالْمَطْعُونُ ‏ ‏وَالْمَبْطُونُ ‏ ‏وَالْهَدِمُ ‏ ‏وَقَالَ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا وَلَوْ يَعْلَمُونَ مَا فِي الصَّفِّ الْمُقَدَّمِ ‏ ‏لَاسْتَهَمُوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a1c75323-4650-5187-9c35-1da002c8b00a', '5cb5e738-220a-4267-901a-841c834b5d56', '680', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَلَا تَخْتَلِفُوا عَلَيْهِ فَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ وَإِذَا سَجَدَ فَاسْجُدُوا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ وَأَقِيمُوا الصَّفَّ فِي الصَّلَاةِ فَإِنَّ إِقَامَةَ الصَّفِّ مِنْ حُسْنِ الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0d2082fa-2906-50b7-b7f0-dea793195735', '5cb5e738-220a-4267-901a-841c834b5d56', '681', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصُّفُوفِ مِنْ إِقَامَةِ الصَّلَاةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9cd84df3-27c7-5bfc-b1b0-fcf2b7618cd3', '5cb5e738-220a-4267-901a-841c834b5d56', '682', '‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ أَسَدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْفَضْلُ بْنُ مُوسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عُبَيْدٍ الطَّائِيُّ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَقِيلَ لَهُ مَا أَنْكَرْتَ مِنَّا مُنْذُ يَوْمِ عَهِدْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَنْكَرْتُ شَيْئًا إِلَّا أَنَّكُمْ لَا تُقِيمُونَ الصُّفُوفَ ‏ ‏وَقَالَ ‏ ‏عُقْبَةُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏الْمَدِينَةَ ‏ ‏بِهَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e2f877df-d2d0-5060-94dd-c6318290fa28', '5cb5e738-220a-4267-901a-841c834b5d56', '683', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِيمُوا صُفُوفَكُمْ فَإِنِّي أَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي ‏ ‏وَكَانَ أَحَدُنَا يُلْزِقُ مَنْكِبَهُ بِمَنْكِبِ صَاحِبِهِ وَقَدَمَهُ بِقَدَمِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8f7bbb84-884b-5289-8b0c-af83f3a6be42', '5cb5e738-220a-4267-901a-841c834b5d56', '684', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَقُمْتُ عَنْ يَسَارِهِ فَأَخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَأْسِي مِنْ وَرَائِي فَجَعَلَنِي عَنْ يَمِينِهِ فَصَلَّى وَرَقَدَ فَجَاءَهُ الْمُؤَذِّنُ فَقَامَ وَصَلَّى وَلَمْ يَتَوَضَّأْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aefbbb18-7d3f-5402-9043-61abf96ef51d', '5cb5e738-220a-4267-901a-841c834b5d56', '685', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ أَنَا وَيَتِيمٌ فِي بَيْتِنَا خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُمِّي ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏خَلْفَنَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('439676ce-79ac-5e9a-a442-bde8d1ff31ca', '5cb5e738-220a-4267-901a-841c834b5d56', '686', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏قُمْتُ لَيْلَةً أُصَلِّي عَنْ يَسَارِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ بِيَدِي أَوْ بِعَضُدِي حَتَّى أَقَامَنِي عَنْ يَمِينِهِ وَقَالَ بِيَدِهِ مِنْ وَرَائِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('edf925f1-9c1f-543b-981c-f05b83214953', '5cb5e738-220a-4267-901a-841c834b5d56', '687', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَامٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فِي حُجْرَتِهِ وَجِدَارُ الْحُجْرَةِ قَصِيرٌ فَرَأَى النَّاسُ شَخْصَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ أُنَاسٌ يُصَلُّونَ بِصَلَاتِهِ فَأَصْبَحُوا فَتَحَدَّثُوا بِذَلِكَ فَقَامَ اللَّيْلَةَ الثَّانِيَةَ فَقَامَ مَعَهُ أُنَاسٌ يُصَلُّونَ بِصَلَاتِهِ صَنَعُوا ذَلِكَ لَيْلَتَيْنِ أَوْ ثَلَاثًا حَتَّى إِذَا كَانَ بَعْدَ ذَلِكَ جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَخْرُجْ فَلَمَّا أَصْبَحَ ذَكَرَ ذَلِكَ النَّاسُ فَقَالَ إِنِّي ‏ ‏خَشِيتُ أَنْ ‏ ‏تُكْتَبَ ‏ ‏عَلَيْكُمْ صَلَاةُ اللَّيْلِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('363ec31c-4ec7-589f-987f-aae6f69d6619', '5cb5e738-220a-4267-901a-841c834b5d56', '688', '‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ الْمُنْذِرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي فُدَيْكٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لَهُ حَصِيرٌ يَبْسُطُهُ بِالنَّهَارِ ‏ ‏وَيَحْتَجِرُهُ ‏ ‏بِاللَّيْلِ ‏ ‏فَثَابَ ‏ ‏إِلَيْهِ نَاسٌ فَصَلَّوْا وَرَاءَهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71506187-e227-5760-9196-c712b8db2593', '5cb5e738-220a-4267-901a-841c834b5d56', '689', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ حَمَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخَذَ حُجْرَةً ‏ ‏قَالَ حَسِبْتُ أَنَّهُ قَالَ مِنْ حَصِيرٍ ‏ ‏فِي رَمَضَانَ فَصَلَّى فِيهَا ‏ ‏لَيَالِيَ فَصَلَّى بِصَلَاتِهِ نَاسٌ مِنْ أَصْحَابِهِ فَلَمَّا عَلِمَ بِهِمْ جَعَلَ يَقْعُدُ فَخَرَجَ إِلَيْهِمْ فَقَالَ قَدْ ‏ ‏عَرَفْتُ الَّذِي رَأَيْتُ مِنْ صَنِيعِكُمْ فَصَلُّوا أَيُّهَا النَّاسُ فِي بُيُوتِكُمْ فَإِنَّ أَفْضَلَ الصَّلَاةِ صَلَاةُ الْمَرْءِ فِي بَيْتِهِ إِلَّا الْمَكْتُوبَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏سَمِعْتُ ‏ ‏أَبَا النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('80f1e63c-e089-50e0-bf2b-acf7724c1824', '5cb5e738-220a-4267-901a-841c834b5d56', '690', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ الْأَنْصَارِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكِبَ فَرَسًا ‏ ‏فَجُحِشَ شِقُّهُ ‏ ‏الْأَيْمَنُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَصَلَّى لَنَا يَوْمَئِذٍ صَلَاةً مِنْ الصَّلَوَاتِ وَهُوَ قَاعِدٌ فَصَلَّيْنَا وَرَاءَهُ قُعُودًا ثُمَّ قَالَ لَمَّا سَلَّمَ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا صَلَّى قَائِمًا فَصَلُّوا قِيَامًا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا سَجَدَ فَاسْجُدُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('80546f8a-f209-5418-96e8-6c0f8fc3d08b', '5cb5e738-220a-4267-901a-841c834b5d56', '691', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏خَرَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ فَرَسٍ ‏ ‏فَجُحِشَ ‏ ‏فَصَلَّى لَنَا قَاعِدًا فَصَلَّيْنَا مَعَهُ قُعُودًا ثُمَّ انْصَرَفَ فَقَالَ ‏ ‏إِنَّمَا الْإِمَامُ أَوْ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا رَفَعَ فَارْفَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا لَكَ الْحَمْدُ وَإِذَا سَجَدَ فَاسْجُدُوا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7d4c7206-dba9-5f33-b801-d03b5af1cda0', '5cb5e738-220a-4267-901a-841c834b5d56', '692', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ وَإِذَا سَجَدَ فَاسْجُدُوا وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da091ed6-cc55-5b5f-a781-154b67c4874f', '5cb5e738-220a-4267-901a-841c834b5d56', '693', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَرْفَعُ يَدَيْهِ ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ‏ ‏إِذَا افْتَتَحَ الصَّلَاةَ وَإِذَا كَبَّرَ لِلرُّكُوعِ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ رَفَعَهُمَا كَذَلِكَ أَيْضًا وَقَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ وَكَانَ لَا يَفْعَلُ ذَلِكَ فِي السُّجُودِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bde50410-a58b-55cf-9d61-f802f6943423', '5cb5e738-220a-4267-901a-841c834b5d56', '694', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُقَاتِلٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ فِي الصَّلَاةِ رَفَعَ يَدَيْهِ حَتَّى يَكُونَا ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَكَانَ يَفْعَلُ ذَلِكَ حِينَ يُكَبِّرُ لِلرُّكُوعِ وَيَفْعَلُ ذَلِكَ إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ وَيَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَلَا يَفْعَلُ ذَلِكَ فِي السُّجُودِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8b9f2899-8c03-5d0c-a1bf-01257b55d095', '5cb5e738-220a-4267-901a-841c834b5d56', '695', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ الْوَاسِطِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏أَنَّهُ رَأَى ‏ ‏مَالِكَ بْنَ الْحُوَيْرِثِ ‏ ‏إِذَا صَلَّى كَبَّرَ وَرَفَعَ يَدَيْهِ وَإِذَا أَرَادَ أَنْ يَرْكَعَ رَفَعَ يَدَيْهِ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ رَفَعَ يَدَيْهِ وَحَدَّثَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ هَكَذَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cf4ecb3c-7ef3-5e31-9186-67798ccf563e', '5cb5e738-220a-4267-901a-841c834b5d56', '696', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏افْتَتَحَ التَّكْبِيرَ فِي الصَّلَاةِ فَرَفَعَ يَدَيْهِ حِينَ يُكَبِّرُ حَتَّى يَجْعَلَهُمَا ‏ ‏حَذْوَ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَإِذَا كَبَّرَ لِلرُّكُوعِ فَعَلَ مِثْلَهُ وَإِذَا قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَعَلَ مِثْلَهُ وَقَالَ رَبَّنَا وَلَكَ الْحَمْدُ وَلَا يَفْعَلُ ذَلِكَ حِينَ يَسْجُدُ وَلَا حِينَ يَرْفَعُ رَأْسَهُ مِنْ السُّجُودِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c104b6b0-f8f2-5c68-bc0f-ac235a756810', '5cb5e738-220a-4267-901a-841c834b5d56', '697', '‏ ‏حَدَّثَنَا ‏ ‏عَيَّاشٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ إِذَا دَخَلَ فِي الصَّلَاةِ كَبَّرَ وَرَفَعَ يَدَيْهِ وَإِذَا رَكَعَ رَفَعَ يَدَيْهِ وَإِذَا قَالَ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ رَفَعَ يَدَيْهِ وَإِذَا قَامَ مِنْ الرَّكْعَتَيْنِ رَفَعَ يَدَيْهِ وَرَفَعَ ذَلِكَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَوَاهُ ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَوَاهُ ‏ ‏ابْنُ طَهْمَانَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏وَمُوسَى بْنِ عُقْبَةَ ‏ ‏مُخْتَصَرًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('16377d2d-54b3-5443-a961-345014f9325c', '5cb5e738-220a-4267-901a-841c834b5d56', '698', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّاسُ يُؤْمَرُونَ ‏ ‏أَنْ يَضَعَ الرَّجُلُ الْيَدَ الْيُمْنَى عَلَى ذِرَاعِهِ الْيُسْرَى فِي الصَّلَاةِ قَالَ ‏ ‏أَبُو حَازِمٍ ‏ ‏لَا أَعْلَمُهُ إِلَّا يَنْمِي ذَلِكَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏يُنْمَى ذَلِكَ وَلَمْ يَقُلْ يَنْمِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0a4d4efa-381f-52b9-b445-512ec3a23116', '5cb5e738-220a-4267-901a-841c834b5d56', '699', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَلْ تَرَوْنَ قِبْلَتِي هَا هُنَا وَاللَّهِ مَا يَخْفَى عَلَيَّ رُكُوعُكُمْ وَلَا خُشُوعُكُمْ وَإِنِّي لأَرَاكُمْ وَرَاءَ ظَهْرِي ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aa6b49bb-1fe3-5330-89a5-e23cccaf8aa2', '5cb5e738-220a-4267-901a-841c834b5d56', '700', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِيمُوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِي وَرُبَّمَا قَالَ مِنْ بَعْدِ ظَهْرِي إِذَا رَكَعْتُمْ وَسَجَدْتُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6346472-35e0-5f09-9b1a-6c8d7f4fca92', '5cb5e738-220a-4267-901a-841c834b5d56', '701', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏كَانُوا يَفْتَتِحُونَ الصَّلَاةَ بِ ‏ { ‏الْحَمْدُ لِلَّهِ ‏ ‏رَبِّ الْعَالَمِينَ ‏ }', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4d00b44a-b311-5af6-9bf3-f76ee304ffe1', '5cb5e738-220a-4267-901a-841c834b5d56', '702', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ الْقَعْقَاعِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو زُرْعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْكُتُ بَيْنَ التَّكْبِيرِ وَبَيْنَ الْقِرَاءَةِ إِسْكَاتَةً ‏ ‏قَالَ أَحْسِبُهُ قَالَ ‏ ‏هُنَيَّةً ‏ ‏فَقُلْتُ بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ إِسْكَاتُكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ مَا تَقُولُ قَالَ أَقُولُ ‏ ‏اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ اللَّهُمَّ نَقِّنِي مِنْ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنْ ‏ ‏الدَّنَسِ ‏ ‏اللَّهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f83930f5-2dd1-59e8-9810-07d88b5eaca3', '5cb5e738-220a-4267-901a-841c834b5d56', '703', '‏ ‏بَاب ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةَ الْكُسُوفِ فَقَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ فَسَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ رَفَعَ ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ ثُمَّ انْصَرَفَ فَقَالَ قَدْ ‏ ‏دَنَتْ مِنِّي الْجَنَّةُ حَتَّى لَوْ ‏ ‏اجْتَرَأْتُ ‏ ‏عَلَيْهَا لَجِئْتُكُمْ ‏ ‏بِقِطَافٍ ‏ ‏مِنْ قِطَافِهَا وَدَنَتْ مِنِّي النَّارُ حَتَّى قُلْتُ أَيْ رَبِّ وَأَنَا مَعَهُمْ فَإِذَا امْرَأَةٌ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ تَخْدِشُهَا هِرَّةٌ ‏ ‏قُلْتُ مَا شَأْنُ هَذِهِ قَالُوا حَبَسَتْهَا حَتَّى مَاتَتْ جُوعًا لَا أَطْعَمَتْهَا وَلَا أَرْسَلَتْهَا تَأْكُلُ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ مِنْ ‏ ‏خَشِيشِ ‏ ‏أَوْ ‏ ‏خَشَاشِ ‏ ‏الْأَرْضِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('23934b0b-0c21-540e-b424-104e8e56735c', '5cb5e738-220a-4267-901a-841c834b5d56', '704', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏قَالَ قُلْنَا ‏ ‏لِخَبَّابٍ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ قَالَ نَعَمْ قُلْنَا بِمَ كُنْتُمْ تَعْرِفُونَ ذَاكَ قَالَ بِاضْطِرَابِ لِحْيَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('69a85565-96b7-5293-95f7-7f93e7a5bc8e', '5cb5e738-220a-4267-901a-841c834b5d56', '705', '‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏يَخْطُبُ قَالَ حَدَّثَنَا ‏ ‏الْبَرَاءُ ‏ ‏وَكَانَ غَيْرَ كَذُوبٍ ‏ ‏أَنَّهُمْ كَانُوا إِذَا صَلَّوْا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ قَامُوا قِيَامًا حَتَّى يَرَوْنَهُ قَدْ سَجَدَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eca2bf1f-539a-5a12-a522-915ddb5aa4c1', '5cb5e738-220a-4267-901a-841c834b5d56', '706', '‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏خَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى قَالُوا يَا رَسُولَ اللَّهِ رَأَيْنَاكَ تَنَاوَلْتَ شَيْئًا فِي مَقَامِكَ ثُمَّ رَأَيْنَاكَ ‏ ‏تَكَعْكَعْتَ ‏ ‏قَالَ ‏ ‏إِنِّي أُرِيتُ الْجَنَّةَ فَتَنَاوَلْتُ مِنْهَا عُنْقُودًا وَلَوْ أَخَذْتُهُ لَأَكَلْتُمْ مِنْهُ مَا بَقِيَتْ الدُّنْيَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e2c506cd-33f7-5770-b3e4-5081266c7d36', '5cb5e738-220a-4267-901a-841c834b5d56', '707', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِنَانٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِلَالُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّى لَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏رَقِيَ ‏ ‏الْمِنْبَرَ فَأَشَارَ بِيَدَيْهِ ‏ ‏قِبَلَ ‏ ‏قِبْلَةِ الْمَسْجِدِ ثُمَّ قَالَ ‏ ‏لَقَدْ رَأَيْتُ الْآنَ مُنْذُ صَلَّيْتُ لَكُمْ الصَّلَاةَ الْجَنَّةَ وَالنَّارَ مُمَثَّلَتَيْنِ فِي قِبْلَةِ هَذَا الْجِدَارِ فَلَمْ أَرَ كَالْيَوْمِ فِي الْخَيْرِ وَالشَّرِّ ثَلَاثًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('77f35c75-9de9-501f-a698-1f9d960690f6', '5cb5e738-220a-4267-901a-841c834b5d56', '708', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُمْ قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي صَلَاتِهِمْ فَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5164a586-0954-5b6c-883c-ebe2c961a961', '5cb5e738-220a-4267-901a-841c834b5d56', '709', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الِالْتِفَاتِ فِي الصَّلَاةِ فَقَالَ ‏ ‏هُوَ ‏ ‏اخْتِلَاسٌ ‏ ‏يَخْتَلِسُهُ ‏ ‏الشَّيْطَانُ مِنْ صَلَاةِ الْعَبْدِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ce42768f-a7fb-55c1-b9c8-bfc8f512f708', '5cb5e738-220a-4267-901a-841c834b5d56', '710', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏خَمِيصَةٍ ‏ ‏لَهَا ‏ ‏أَعْلَامٌ ‏ ‏فَقَالَ ‏ ‏شَغَلَتْنِي ‏ ‏أَعْلَامُ ‏ ‏هَذِهِ اذْهَبُوا بِهَا إِلَى ‏ ‏أَبِي جَهْمٍ ‏ ‏وَأْتُونِي ‏ ‏بِأَنْبِجَانِيَّةٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d6db0073-25a6-5b72-84ba-8d9802b6f62f', '5cb5e738-220a-4267-901a-841c834b5d56', '711', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ رَأَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُخَامَةً فِي قِبْلَةِ الْمَسْجِدِ وَهُوَ ‏ ‏يُصَلِّي بَيْنَ يَدَيْ النَّاسِ فَحَتَّهَا ثُمَّ قَالَ حِينَ انْصَرَفَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا كَانَ فِي الصَّلَاةِ فَإِنَّ اللَّهَ ‏ ‏قِبَلَ ‏ ‏وَجْهِهِ فَلَا يَتَنَخَّمَنَّ أَحَدٌ ‏ ‏قِبَلَ ‏ ‏وَجْهِهِ فِي الصَّلَاةِ ‏ ‏رَوَاهُ ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏وَابْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1846009d-978f-56ef-ad06-b86654fd1c9c', '5cb5e738-220a-4267-901a-841c834b5d56', '712', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا الْمُسْلِمُونَ فِي صَلَاةِ الْفَجْرِ لَمْ يَفْجَأْهُمْ إِلَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَشَفَ سِتْرَ حُجْرَةِ ‏ ‏عَائِشَةَ ‏ ‏فَنَظَرَ إِلَيْهِمْ وَهُمْ صُفُوفٌ فَتَبَسَّمَ يَضْحَكُ ‏ ‏وَنَكَصَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَلَى عَقِبَيْهِ لِيَصِلَ لَهُ الصَّفَّ فَظَنَّ أَنَّهُ يُرِيدُ الْخُرُوجَ وَهَمَّ الْمُسْلِمُونَ أَنْ ‏ ‏يَفْتَتِنُوا ‏ ‏فِي صَلَاتِهِمْ فَأَشَارَ إِلَيْهِمْ أَتِمُّوا صَلَاتَكُمْ فَأَرْخَى السِّتْرَ وَتُوُفِّيَ مِنْ آخِرِ ذَلِكَ الْيَوْمِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0270c824-4137-5093-80e4-418841bcc828', '5cb5e738-220a-4267-901a-841c834b5d56', '713', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏شَكَا ‏ ‏أَهْلُ ‏ ‏الْكُوفَةِ ‏ ‏سَعْدًا ‏ ‏إِلَى ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَعَزَلَهُ وَاسْتَعْمَلَ عَلَيْهِمْ ‏ ‏عَمَّارًا ‏ ‏فَشَكَوْا حَتَّى ذَكَرُوا أَنَّهُ لَا يُحْسِنُ ‏ ‏يُصَلِّي فَأَرْسَلَ إِلَيْهِ فَقَالَ يَا ‏ ‏أَبَا إِسْحَاقَ ‏ ‏إِنَّ هَؤُلَاءِ يَزْعُمُونَ أَنَّكَ لَا تُحْسِنُ تُصَلِّي قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَمَّا أَنَا وَاللَّهِ ‏ ‏فَإِنِّي كُنْتُ أُصَلِّي بِهِمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏أَخْرِمُ ‏ ‏عَنْهَا أُصَلِّي صَلَاةَ الْعِشَاءِ ‏ ‏فَأَرْكُدُ ‏ ‏فِي الْأُولَيَيْنِ وَأُخِفُّ فِي الْأُخْرَيَيْنِ قَالَ ذَاكَ الظَّنُّ بِكَ يَا ‏ ‏أَبَا إِسْحَاقَ ‏ ‏فَأَرْسَلَ مَعَهُ رَجُلًا أَوْ رِجَالًا إِلَى ‏ ‏الْكُوفَةِ ‏ ‏فَسَأَلَ عَنْهُ ‏ ‏أَهْلَ ‏ ‏الْكُوفَةِ ‏ ‏وَلَمْ يَدَعْ مَسْجِدًا إِلَّا سَأَلَ عَنْهُ وَيُثْنُونَ مَعْرُوفًا حَتَّى دَخَلَ مَسْجِدًا ‏ ‏لِبَنِي عَبْسٍ ‏ ‏فَقَامَ رَجُلٌ مِنْهُمْ يُقَالُ لَهُ ‏ ‏أُسَامَةُ بْنُ قَتَادَةَ ‏ ‏يُكْنَى ‏ ‏أَبَا سَعْدَةَ ‏ ‏قَالَ أَمَّا إِذْ نَشَدْتَنَا فَإِنَّ ‏ ‏سَعْدًا ‏ ‏كَانَ لَا يَسِيرُ ‏ ‏بِالسَّرِيَّةِ ‏ ‏وَلَا يَقْسِمُ بِالسَّوِيَّةِ وَلَا يَعْدِلُ فِي الْقَضِيَّةِ قَالَ ‏ ‏سَعْدٌ ‏ ‏أَمَا وَاللَّهِ لَأَدْعُوَنَّ بِثَلَاثٍ اللَّهُمَّ إِنْ كَانَ عَبْدُكَ هَذَا كَاذِبًا قَامَ رِيَاءً وَسُمْعَةً فَأَطِلْ عُمْرَهُ وَأَطِلْ فَقْرَهُ وَعَرِّضْهُ بِالْفِتَنِ وَكَانَ بَعْدُ إِذَا سُئِلَ يَقُولُ شَيْخٌ كَبِيرٌ مَفْتُونٌ أَصَابَتْنِي دَعْوَةُ ‏ ‏سَعْدٍ ‏ ‏قَالَ ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏فَأَنَا رَأَيْتُهُ بَعْدُ قَدْ سَقَطَ حَاجِبَاهُ عَلَى عَيْنَيْهِ مِنْ الْكِبَرِ وَإِنَّهُ لَيَتَعَرَّضُ لِلْجَوَارِي فِي الطُّرُقِ يَغْمِزُهُنَّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('345c24ab-8b71-5681-946e-b60b1e06e434', '5cb5e738-220a-4267-901a-841c834b5d56', '714', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('42619867-7de9-52b9-bbef-0f81d488d62b', '5cb5e738-220a-4267-901a-841c834b5d56', '715', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ الْمَسْجِدَ فَدَخَلَ رَجُلٌ فَصَلَّى فَسَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَدَّ وَقَالَ ‏ ‏ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ فَرَجَعَ ‏ ‏يُصَلِّي كَمَا صَلَّى ثُمَّ جَاءَ فَسَلَّمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ ثَلَاثًا فَقَالَ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أُحْسِنُ غَيْرَهُ فَعَلِّمْنِي فَقَالَ إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنْ الْقُرْآنِ ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا ثُمَّ ارْفَعْ حَتَّى تَعْدِلَ قَائِمًا ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا وَافْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6fd2d621-1e50-56dd-82e1-a0b1f175da9d', '5cb5e738-220a-4267-901a-841c834b5d56', '716', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سَمُرَةَ ‏ ‏قَالَ قَالَ ‏ ‏سَعْدٌ ‏ ‏كُنْتُ أُصَلِّي بِهِمْ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاتَيْ الْعَشِيِّ لَا ‏ ‏أَخْرِمُ ‏ ‏عَنْهَا ‏ ‏أَرْكُدُ ‏ ‏فِي الْأُولَيَيْنِ وَأَحْذِفُ فِي الْأُخْرَيَيْنِ فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏ذَلِكَ الظَّنُّ بِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ca65a082-0055-571a-a179-8ebd660b2483', '5cb5e738-220a-4267-901a-841c834b5d56', '717', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الظُّهْرِ بِفَاتِحَةِ الْكِتَابِ وَسُورَتَيْنِ يُطَوِّلُ فِي الْأُولَى وَيُقَصِّرُ فِي الثَّانِيَةِ وَيُسْمِعُ الْآيَةَ أَحْيَانًا وَكَانَ يَقْرَأُ فِي الْعَصْرِ بِفَاتِحَةِ الْكِتَابِ وَسُورَتَيْنِ وَكَانَ يُطَوِّلُ فِي الْأُولَى وَكَانَ يُطَوِّلُ فِي الرَّكْعَةِ الْأُولَى مِنْ صَلَاةِ الصُّبْحِ وَيُقَصِّرُ فِي الثَّانِيَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('81c8d0a4-ac8c-56ad-9494-50c725ab1d2e', '5cb5e738-220a-4267-901a-841c834b5d56', '718', '‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏قَالَ سَأَلْنَا ‏ ‏خَبَّابًا ‏ ‏أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ قَالَ نَعَمْ قُلْنَا بِأَيِّ شَيْءٍ كُنْتُمْ تَعْرِفُونَ قَالَ بِاضْطِرَابِ لِحْيَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e494a7e9-b475-5cd4-a300-35f52732c172', '5cb5e738-220a-4267-901a-841c834b5d56', '719', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِخَبَّابِ بْنِ الْأَرَتِّ ‏ ‏أَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ قَالَ نَعَمْ قَالَ قُلْتُ بِأَيِّ شَيْءٍ كُنْتُمْ تَعْلَمُونَ قِرَاءَتَهُ قَالَ بِاضْطِرَابِ لِحْيَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b8cac864-94dc-5345-85fb-1a6b0060d257', '5cb5e738-220a-4267-901a-841c834b5d56', '720', '‏ ‏حَدَّثَنَا ‏ ‏الْمَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الرَّكْعَتَيْنِ مِنْ الظُّهْرِ وَالْعَصْرِ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏وَسُورَةٍ سُورَةٍ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('301d0822-1410-5214-8ce2-21829c9647e0', '5cb5e738-220a-4267-901a-841c834b5d56', '721', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّهُ قَالَ إِنَّ ‏ ‏أُمَّ الْفَضْلِ ‏ ‏سَمِعَتْهُ وَهُوَ يَقْرَأُ ‏ ‏وَالْمُرْسَلَاتِ ‏ ‏عُرْفًا ‏ ‏فَقَالَتْ يَا بُنَيَّ وَاللَّهِ لَقَدْ ذَكَّرْتَنِي بِقِرَاءَتِكَ هَذِهِ السُّورَةَ ‏ ‏إِنَّهَا لَآخِرُ مَا سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا فِي الْمَغْرِبِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e41055ff-e5a1-5933-bad7-236d54460f3a', '5cb5e738-220a-4267-901a-841c834b5d56', '722', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏قَالَ قَالَ لِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏مَا لَكَ تَقْرَأُ فِي الْمَغْرِبِ بِقِصَارٍ وَقَدْ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ ‏ ‏بِطُولَى الطُّولَيَيْنِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cdf29814-05c4-5473-91af-82bbb8a1c314', '5cb5e738-220a-4267-901a-841c834b5d56', '723', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَرَأَ فِي الْمَغْرِبِ ‏ ‏بِالطُّورِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f680cac0-af2f-543f-90d7-5e8558660e2c', '5cb5e738-220a-4267-901a-841c834b5d56', '724', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏الْعَتَمَةَ ‏ ‏فَقَرَأَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَسَجَدَ فَقُلْتُ لَهُ قَالَ ‏ ‏سَجَدْتُ خَلْفَ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا أَزَالُ أَسْجُدُ بِهَا حَتَّى أَلْقَاهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c6f0ab25-d13d-5fcb-9103-1cb282e04d9a', '5cb5e738-220a-4267-901a-841c834b5d56', '725', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ ‏ ‏فَقَرَأَ فِي الْعِشَاءِ فِي إِحْدَى الرَّكْعَتَيْنِ ‏ ‏بِالتِّينِ وَالزَّيْتُونِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3d3b5467-1999-55fc-b155-7d989337631c', '5cb5e738-220a-4267-901a-841c834b5d56', '726', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏الْعَتَمَةَ ‏ ‏فَقَرَأَ ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏ ‏فَسَجَدَ فَقُلْتُ مَا هَذِهِ قَالَ ‏ ‏سَجَدْتُ بِهَا خَلْفَ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا أَزَالُ أَسْجُدُ بِهَا حَتَّى أَلْقَاهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5afd46ff-21ec-51e5-90be-297cebb9e124', '5cb5e738-220a-4267-901a-841c834b5d56', '727', '‏ ‏حَدَّثَنَا ‏ ‏خَلَّادُ بْنُ يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏سَمِعَ ‏ ‏الْبَرَاءَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ ‏ ‏وَالتِّينِ وَالزَّيْتُونِ ‏ ‏فِي الْعِشَاءِ وَمَا سَمِعْتُ أَحَدًا أَحْسَنَ صَوْتًا مِنْهُ أَوْ قِرَاءَةً ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('be02cc6f-ae70-5657-8ab1-08e17fa0122b', '5cb5e738-220a-4267-901a-841c834b5d56', '728', '‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عَوْنٍ مُحَمَّدِ بْنِ عُبَيْدِ اللَّهِ الثَّقَفِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرَ بْنَ سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏لِسَعْدٍ ‏ ‏لَقَدْ شَكَوْكَ فِي كُلِّ شَيْءٍ حَتَّى الصَّلَاةِ قَالَ ‏ ‏أَمَّا أَنَا ‏ ‏فَأَمُدُّ ‏ ‏فِي الْأُولَيَيْنِ ‏ ‏وَأَحْذِفُ ‏ ‏فِي الْأُخْرَيَيْنِ وَلَا ‏ ‏آلُو ‏ ‏مَا اقْتَدَيْتُ بِهِ مِنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ صَدَقْتَ ذَاكَ الظَّنُّ بِكَ أَوْ ظَنِّي بِكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('70bf3638-4e28-5c3a-8d2c-9c8cda458a8f', '5cb5e738-220a-4267-901a-841c834b5d56', '729', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَيَّارُ بْنُ سَلَامَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا وَأَبِي عَلَى ‏ ‏أَبِي بَرْزَةَ الْأَسْلَمِيِّ ‏ ‏فَسَأَلْنَاهُ عَنْ وَقْتِ الصَّلَوَاتِ فَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الظُّهْرَ حِينَ ‏ ‏تَزُولُ ‏ ‏الشَّمْسُ وَالْعَصْرَ وَيَرْجِعُ الرَّجُلُ إِلَى أَقْصَى ‏ ‏الْمَدِينَةِ ‏ ‏وَالشَّمْسُ ‏ ‏حَيَّةٌ ‏ ‏وَنَسِيتُ مَا قَالَ فِي الْمَغْرِبِ وَلَا يُبَالِي بِتَأْخِيرِ الْعِشَاءِ إِلَى ثُلُثِ اللَّيْلِ وَلَا يُحِبُّ النَّوْمَ قَبْلَهَا وَلَا الْحَدِيثَ بَعْدَهَا وَيُصَلِّي الصُّبْحَ فَيَنْصَرِفُ الرَّجُلُ فَيَعْرِفُ جَلِيسَهُ وَكَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ أَوْ إِحْدَاهُمَا مَا بَيْنَ السِّتِّينَ إِلَى الْمِائَةِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4b5c5eb4-8762-5f05-ba48-63e9117edbfe', '5cb5e738-220a-4267-901a-841c834b5d56', '730', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏فِي كُلِّ صَلَاةٍ يُقْرَأُ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَنَّا أَخْفَيْنَا عَنْكُمْ وَإِنْ لَمْ تَزِدْ عَلَى ‏ ‏أُمِّ الْقُرْآنِ ‏ ‏أَجْزَأَتْ وَإِنْ زِدْتَ فَهُوَ خَيْرٌ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a9fdaf92-976e-5ae5-8d10-3b530217de4c', '5cb5e738-220a-4267-901a-841c834b5d56', '731', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ هُوَ جَعْفَرُ بْنُ أَبِي وَحْشِيَّةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏انْطَلَقَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَائِفَةٍ مِنْ أَصْحَابِهِ ‏ ‏عَامِدِينَ ‏ ‏إِلَى سُوقِ ‏ ‏عُكَاظٍ ‏ ‏وَقَدْ حِيلَ بَيْنَ الشَّيَاطِينِ وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْهِمْ الشُّهُبُ فَرَجَعَتْ الشَّيَاطِينُ إِلَى قَوْمِهِمْ فَقَالُوا مَا لَكُمْ فَقَالُوا حِيلَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْنَا الشُّهُبُ قَالُوا مَا حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ إِلَّا شَيْءٌ حَدَثَ فَاضْرِبُوا مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا فَانْظُرُوا مَا هَذَا الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ فَانْصَرَفَ أُولَئِكَ الَّذِينَ تَوَجَّهُوا نَحْوَ ‏ ‏تِهَامَةَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِنَخْلَةَ ‏ ‏عَامِدِينَ ‏ ‏إِلَى سُوقِ ‏ ‏عُكَاظٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي بِأَصْحَابِهِ صَلَاةَ الْفَجْرِ فَلَمَّا سَمِعُوا الْقُرْآنَ اسْتَمَعُوا لَهُ فَقَالُوا هَذَا وَاللَّهِ الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ فَهُنَالِكَ حِينَ رَجَعُوا إِلَى قَوْمِهِمْ وَقَالُوا يَا قَوْمَنَا ‏ { ‏إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ وَلَنْ نُشْرِكَ بِرَبِّنَا أَحَدًا ‏} ‏فَأَنْزَلَ اللَّهُ عَلَى نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِنْ الْجِنِّ ‏} ‏وَإِنَّمَا أُوحِيَ إِلَيْهِ قَوْلُ الْجِنِّ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa978528-f33a-57b7-8bc2-ba0580879048', '5cb5e738-220a-4267-901a-841c834b5d56', '732', '‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَرَأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا أُمِرَ وَسَكَتَ فِيمَا أُمِرَ ‏ { ‏وَمَا كَانَ رَبُّكَ نَسِيًّا ‏} { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏}', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('552f4db4-5cb5-5a4b-94d1-e3cb63ab4918', '5cb5e738-220a-4267-901a-841c834b5d56', '733', '‏ ‏حَدَّثَنَا ‏ ‏آدَمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏رَجُلٌ ‏ ‏إِلَى ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏فَقَالَ قَرَأْتُ ‏ ‏الْمُفَصَّلَ ‏ ‏اللَّيْلَةَ فِي رَكْعَةٍ فَقَالَ هَذًّا كَهَذِّ الشِّعْرِ ‏ ‏لَقَدْ عَرَفْتُ ‏ ‏النَّظَائِرَ ‏ ‏الَّتِي كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرُنُ بَيْنَهُنَّ فَذَكَرَ عِشْرِينَ سُورَةً مِنْ ‏ ‏الْمُفَصَّلِ ‏ ‏سُورَتَيْنِ فِي كُلِّ رَكْعَةٍ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a242a923-f232-5ed4-ba89-40d1c77841c3', '5cb5e738-220a-4267-901a-841c834b5d56', '734', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ فِي الْأُولَيَيْنِ ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏وَسُورَتَيْنِ وَفِي الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏وَيُسْمِعُنَا الْآيَةَ وَيُطَوِّلُ فِي الرَّكْعَةِ الْأُولَى مَا لَا يُطَوِّلُ فِي الرَّكْعَةِ الثَّانِيَةِ وَهَكَذَا فِي الْعَصْرِ وَهَكَذَا فِي الصُّبْحِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6835c2c5-cc4b-5dba-8a22-33eb89446d55', '5cb5e738-220a-4267-901a-841c834b5d56', '735', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْمَرٍ ‏ ‏قُلْتُ ‏ ‏لِخَبَّابٍ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ قَالَ نَعَمْ قُلْنَا مِنْ أَيْنَ عَلِمْتَ قَالَ بِاضْطِرَابِ لِحْيَتِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d8c10ac3-1fd1-569b-b845-bba82bc50b9b', '5cb5e738-220a-4267-901a-841c834b5d56', '736', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏وَسُورَةٍ مَعَهَا فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الظُّهْرِ وَصَلَاةِ الْعَصْرِ وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا وَكَانَ يُطِيلُ فِي الرَّكْعَةِ الْأُولَى ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a8d4cbd-4505-5f6a-bb21-1b70157e96d8', '5cb5e738-220a-4267-901a-841c834b5d56', '737', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُطَوِّلُ فِي الرَّكْعَةِ الْأُولَى مِنْ صَلَاةِ الظُّهْرِ وَيُقَصِّرُ فِي الثَّانِيَةِ وَيَفْعَلُ ذَلِكَ فِي صَلَاةِ الصُّبْحِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6196c72f-2069-5f7e-a544-3cecbe09aa74', '5cb5e738-220a-4267-901a-841c834b5d56', '738', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُمَا أَخْبَرَاهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَمَّنَ الْإِمَامُ فَأَمِّنُوا فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏وَقَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ آمِينَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a7612974-1058-5986-972f-cb0d50c63a77', '5cb5e738-220a-4267-901a-841c834b5d56', '739', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ أَحَدُكُمْ آمِينَ وَقَالَتْ الْمَلَائِكَةُ فِي السَّمَاءِ آمِينَ فَوَافَقَتْ إِحْدَاهُمَا الْأُخْرَى غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7a941d7f-4b52-5347-b3a8-06e66c80cf16', '5cb5e738-220a-4267-901a-841c834b5d56', '740', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا قَالَ الْإِمَامُ ‏ { ‏غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏فَقُولُوا آمِينَ فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏ ‏تَابَعَهُ ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنُعَيْمٌ الْمُجْمِرُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b2334c9e-9363-5077-b0ac-a5b886ce3e2a', '5cb5e738-220a-4267-901a-841c834b5d56', '741', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏الْأَعْلَمِ وَهُوَ زِيَادٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّهُ انْتَهَى إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ رَاكِعٌ فَرَكَعَ قَبْلَ أَنْ يَصِلَ إِلَى الصَّفِّ فَذَكَرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏زَادَكَ اللَّهُ حِرْصًا وَلَا تَعُدْ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('04a2b95b-589a-5348-bc02-02d5a1e5634a', '5cb5e738-220a-4267-901a-841c834b5d56', '742', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ الْوَاسِطِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏صَلَّى مَعَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏بِالْبَصْرَةِ ‏ ‏فَقَالَ ‏ ‏ذَكَّرَنَا هَذَا الرَّجُلُ صَلَاةً كُنَّا نُصَلِّيهَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَنَّهُ كَانَ يُكَبِّرُ كُلَّمَا رَفَعَ وَكُلَّمَا وَضَعَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('88426acd-b2de-548f-8568-8ad2fe9366a1', '5cb5e738-220a-4267-901a-841c834b5d56', '743', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي بِهِمْ فَيُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ فَإِذَا انْصَرَفَ قَالَ إِنِّي لَأَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('90310c77-9e1a-5a9a-a1ca-afdc85adeb1e', '5cb5e738-220a-4267-901a-841c834b5d56', '744', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏غَيْلَانَ بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ ‏ ‏عَلِيِّ بْنِ أَبِي طَالِبٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَا ‏ ‏وَعِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَكَانَ إِذَا سَجَدَ كَبَّرَ وَإِذَا رَفَعَ رَأْسَهُ كَبَّرَ وَإِذَا نَهَضَ مِنْ الرَّكْعَتَيْنِ كَبَّرَ فَلَمَّا قَضَى الصَّلَاةَ أَخَذَ بِيَدِي ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَقَالَ قَدْ ‏ ‏ذَكَّرَنِي هَذَا صَلَاةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ لَقَدْ صَلَّى بِنَا صَلَاةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('471d6edd-3847-589d-9c9b-6044e308a82a', '5cb5e738-220a-4267-901a-841c834b5d56', '745', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏رَجُلًا ‏ ‏عِنْدَ الْمَقَامِ يُكَبِّرُ فِي كُلِّ خَفْضٍ وَرَفْعٍ وَإِذَا قَامَ وَإِذَا وَضَعَ فَأَخْبَرْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏أَوَلَيْسَ تِلْكَ صَلَاةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أُمَّ لَكَ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bdae564e-7b86-54aa-bb0e-6acf3f52e440', '5cb5e738-220a-4267-901a-841c834b5d56', '746', '‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ إِسْمَاعِيلَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ شَيْخٍ ‏ ‏بِمَكَّةَ ‏ ‏فَكَبَّرَ ثِنْتَيْنِ وَعِشْرِينَ تَكْبِيرَةً فَقُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏إِنَّهُ أَحْمَقُ فَقَالَ ‏ ‏ثَكِلَتْكَ ‏ ‏أُمُّكَ سُنَّةُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e13f76d7-b170-5d43-8ed5-4080c2bbbe7e', '5cb5e738-220a-4267-901a-841c834b5d56', '747', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ ثُمَّ يَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ حِينَ يَرْفَعُ ‏ ‏صُلْبَهُ ‏ ‏مِنْ الرَّكْعَةِ ثُمَّ يَقُولُ وَهُوَ قَائِمٌ رَبَّنَا لَكَ الْحَمْدُ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏اللَّيْثِ ‏ ‏وَلَكَ الْحَمْدُ ثُمَّ يُكَبِّرُ حِينَ يَهْوِي ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يُكَبِّرُ حِينَ يَسْجُدُ ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ ثُمَّ يَفْعَلُ ذَلِكَ فِي الصَّلَاةِ كُلِّهَا حَتَّى يَقْضِيَهَا وَيُكَبِّرُ حِينَ يَقُومُ مِنْ الثِّنْتَيْنِ بَعْدَ الْجُلُوسِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6fab6fee-eba2-53aa-85b3-e7acc7000eb2', '5cb5e738-220a-4267-901a-841c834b5d56', '748', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي يَعْفُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُصْعَبَ بْنَ سَعْدٍ ‏ ‏يَقُولُ ‏ ‏صَلَّيْتُ إِلَى جَنْبِ ‏ ‏أَبِي ‏ ‏فَطَبَّقْتُ بَيْنَ كَفَّيَّ ثُمَّ وَضَعْتُهُمَا بَيْنَ فَخِذَيَّ فَنَهَانِي أَبِي وَقَالَ كُنَّا نَفْعَلُهُ فَنُهِينَا عَنْهُ ‏ ‏وَأُمِرْنَا أَنْ نَضَعَ أَيْدِينَا عَلَى الرُّكَبِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4d3da68b-6c45-5ab7-bdbc-b548017157ff', '5cb5e738-220a-4267-901a-841c834b5d56', '749', '‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ وَهْبٍ ‏ ‏قَالَ رَأَى ‏ ‏حُذَيْفَةُ ‏ ‏رَجُلًا لَا يُتِمُّ الرُّكُوعَ وَالسُّجُودَ قَالَ ‏ ‏مَا صَلَّيْتَ وَلَوْ مُتَّ مُتَّ عَلَى غَيْرِ الْفِطْرَةِ الَّتِي فَطَرَ اللَّهُ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهَا ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('87b7859c-8b5f-55f4-9131-46bb2d05479a', '5cb5e738-220a-4267-901a-841c834b5d56', '750', '‏ ‏حَدَّثَنَا ‏ ‏بَدَلُ بْنُ الْمُحَبَّرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏كَانَ رُكُوعُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسُجُودُهُ وَبَيْنَ السَّجْدَتَيْنِ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ مَا خَلَا الْقِيَامَ وَالْقُعُودَ قَرِيبًا مِنْ السَّوَاءِ ‏', 'صحيح البخاري — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
